window.FM_DATA["ui"] = {"id":"ui","title":"UI Toolkit","entries":[{"id":"accordion-panel","name":"AccordionPanel","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/Layouts/AccordionPanel.cs","src_lines":[15,71],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Accordion Panel"},"src_typeComment":"Expand/collapse a content region with an animated height, driven by the EXISTING Tween engine and a LayoutElement.preferredHeight override — works inside any VerticalLayoutGroup (a FAQ list, a settings category list) since the layout group re-flows around the animating height automatically. Wiring a header click to Toggle() is left to the caller (e.g. a Button.onClick) rather than baked in here, matching this toolkit's \"primitives, not opinionated\" pattern.","src_serialized":[{"name":"content","type":"RectTransform","default":null,"tooltip":"The collapsible body. Its natural (expanded) height is captured once, from its RectTransform's height, before any collapsing happens — make sure it's sized to its full expanded height in the scene/prefab.","header":null,"range":null,"order":0,"comment":null},{"name":"startExpanded","type":"bool","default":"true","tooltip":null,"header":null,"range":null,"order":1,"comment":null},{"name":"animationDuration","type":"float","default":"0.25f","tooltip":null,"header":null,"range":null,"order":2,"comment":null}],"src_members":[{"id":"UnityEvent<bool>()","sig":"public UnityEvent<bool> OnToggled = new UnityEvent<bool>()","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"IsExpanded","sig":"public bool IsExpanded { get; private set; }","kind":"property","name":"IsExpanded","static":false,"comment":null},{"id":"Toggle()","sig":"public void Toggle() => SetExpanded(!IsExpanded)","kind":"method","name":"Toggle","static":false,"comment":null},{"id":"SetExpanded(bool, bool)","sig":"public void SetExpanded(bool expanded, bool animate = true)","kind":"method","name":"SetExpanded","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UIDev_Demo"],"entryKind":"tool","status":"published","summary":"Expand and collapse a region with an animated height that a layout group re-flows around.","overview":["Animates a content region open and closed by driving a LayoutElement's preferred height through the tween engine. Because it animates the LAYOUT value rather than the transform, a surrounding VerticalLayoutGroup re-flows around it — which is what makes a FAQ list or a settings category list work."],"useCases":["FAQ or help sections that expand one at a time.","Settings grouped into collapsible categories.","A details panel that reveals more without a new screen."],"params":[{"field":"content","tuning":"Its natural expanded height is captured, so the content must be laid out correctly before the first collapse."},{"field":"animationDuration","tuning":"Every frame of the animation re-flows the parent layout, so long durations on a large list are the expensive case."}],"gotchas":[{"title":"It animates layout, not the transform","body":"That is what lets neighbours move out of the way, and it means the cost is a layout rebuild per frame rather than a cheap position change."}],"seeAlso":["Tween","DeferredLayoutRebuilder","TabGroup"],"src_uses":["EaseType","Tween","TweenHandle"],"src_usedBy":["TabEntry","TabGroup"],"src_extensionPoints":[]},{"id":"card-carousel","name":"CardCarousel","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/Layouts/CardCarousel.cs","src_lines":[13,76],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Card Carousel"},"src_typeComment":"Swipeable stacked-card layout (a deck) — Next()/Previous()/GoTo() ease every card to its position/scale for the new current index, with siblings behind the front card peeking out to the side and shrinking. Drag-to-advance isn't built in here — wire a DraggableItem or raw pointer-delta on the front card to call Next()/Previous(), keeping this component focused on the layout math itself.","src_serialized":[{"name":"cards","type":"RectTransform[]","default":null,"tooltip":null,"header":null,"range":null,"order":0,"comment":null},{"name":"scaleStepDown","type":"float","default":"0.15f","tooltip":"How much each card behind the front one shrinks, per step back — 0.15 = 15% smaller per step.","header":null,"range":null,"order":1,"comment":null},{"name":"peekOffset","type":"float","default":"40f","tooltip":"Horizontal offset, in UI units, between each stacked card.","header":null,"range":null,"order":2,"comment":null},{"name":"animationDuration","type":"float","default":"0.3f","tooltip":null,"header":null,"range":null,"order":3,"comment":null}],"src_members":[{"id":"UnityEvent<int>()","sig":"public UnityEvent<int> OnCardChanged = new UnityEvent<int>()","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"CurrentIndex","sig":"public int CurrentIndex { get; private set; }","kind":"property","name":"CurrentIndex","static":false,"comment":null},{"id":"CardCount","sig":"public int CardCount => cards != null ? cards.Length : 0","kind":"property","name":"CardCount","static":false,"comment":null},{"id":"Next()","sig":"public void Next() => GoTo(CurrentIndex + 1)","kind":"method","name":"Next","static":false,"comment":null},{"id":"Previous()","sig":"public void Previous() => GoTo(CurrentIndex - 1)","kind":"method","name":"Previous","static":false,"comment":null},{"id":"GoTo(int)","sig":"public void GoTo(int index)","kind":"method","name":"GoTo","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UIDev_Demo","UIExtras_Demo"],"entryKind":"tool","status":"published","summary":"Swipeable stacked-card deck, with siblings peeking out behind the front card.","overview":["Next, Previous and GoTo ease every card to its position and scale for the new index, with the cards behind peeking out and shrinking. Drag-to-advance is deliberately not built in — wire a draggable or raw pointer delta on the front card to whichever method suits."],"useCases":["A card-based character or level selector.","An onboarding flow of stacked pages.","A deck of items the player flicks through."],"params":[{"field":"scaleStepDown","tuning":"How much each card behind shrinks. Small values read as a thick deck; large ones as a receding tunnel."},{"field":"peekOffset","tuning":"How far the cards behind stick out. Zero hides them entirely and the deck reads as a single card."}],"gotchas":[{"title":"Dragging is not included","body":"It exposes the methods and leaves the gesture to you, so it does not fight whatever input system you use."}],"seeAlso":["PaginationDots","ScrollSnap","DraggableItem"],"src_uses":["DraggableItem","EaseType","Tween"],"src_usedBy":["PaginationDots","TabEntry","TabGroup"],"src_extensionPoints":[]},{"id":"masonry-layout-group","name":"MasonryLayoutGroup","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/Layouts/MasonryLayoutGroup.cs","src_lines":[12,59],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Masonry Layout Group"},"src_typeComment":"Pinterest-style variable-height grid: each child keeps its OWN height, packed into whichever column is currently shortest — unlike GridLayoutGroup's uniform cell size. Deliberately a plain MonoBehaviour with an explicit Rebuild() call rather than a full ILayoutGroup/LayoutGroup subclass (which would auto-rebuild on every RectTransform change like Unity's built-in layout groups do) — implementing that integration correctly needs more Unity layout-system plumbing than this tool's value justified; call Rebuild() yourself after adding/removing/resizing children (Start() calls it once automatically).","src_serialized":[{"name":"columnCount","type":"int","default":"3","tooltip":null,"header":null,"range":null,"order":0,"comment":null},{"name":"spacing","type":"float","default":"8f","tooltip":null,"header":null,"range":null,"order":1,"comment":null},{"name":"paddingLeft","type":"float","default":"8f","tooltip":null,"header":null,"range":null,"order":2,"comment":null},{"name":"paddingTop","type":"float","default":"8f","tooltip":null,"header":null,"range":null,"order":3,"comment":null},{"name":"paddingRight","type":"float","default":"8f","tooltip":null,"header":null,"range":null,"order":4,"comment":null},{"name":"paddingBottom","type":"float","default":"8f","tooltip":null,"header":null,"range":null,"order":5,"comment":null}],"src_members":[{"id":"Rebuild()","sig":"public void Rebuild()","kind":"method","name":"Rebuild","static":false,"comment":"Re-packs every active child into the shortest-so-far column, top-left anchored, uniform width (columnWidth) but each child's OWN height left untouched — that per-child height variance is the entire point of a masonry layout. Resizes this container's own height to fit the tallest column."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UIDev_Demo"],"entryKind":"tool","status":"published","summary":"Pinterest-style grid where each child keeps its own height, packed into the shortest column.","overview":["Variable-height children packed into whichever column is currently shortest, unlike GridLayoutGroup's uniform cells. Deliberately a plain component with an explicit Rebuild rather than a full LayoutGroup subclass, which would fight Unity's own layout system over variable heights."],"useCases":["An image gallery where pictures differ in aspect.","A card feed with entries of different lengths.","Any grid where forcing uniform cells would waste space."],"params":[{"field":"columnCount","tuning":"Fixed, not responsive. Changing it for different screen widths is your code's job."}],"gotchas":[{"title":"You must call Rebuild","body":"It does not reflow automatically when children change. That is the trade for not fighting Unity's layout system."}],"seeAlso":["RadialLayoutGroup","DeferredLayoutRebuilder"],"src_uses":[],"src_usedBy":[],"src_extensionPoints":[]},{"id":"radial-layout-group","name":"RadialLayoutGroup","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/RadialLayoutGroup/RadialLayoutGroup.cs","src_lines":[9,74],"src_base":"LayoutGroup","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Layout/Radial Layout Group"},"src_typeComment":"Drop this on a UI panel instead of Horizontal/Vertical Layout Group to arrange children in a circle or arc. Zero setup beyond adding the component — children snap into place automatically like any other LayoutGroup.","src_serialized":[{"name":"radius","type":"float","default":"150f","tooltip":"Distance from center to each child's pivot.","header":null,"range":null,"order":0,"comment":null},{"name":"startAngle","type":"float","default":"0f","tooltip":"Angle in degrees where the first child is placed. 0 = up, measured clockwise.","header":null,"range":null,"order":1,"comment":null},{"name":"arcDegrees","type":"float","default":"360f","tooltip":"Total arc in degrees the children are spread across. 360 = full circle, evenly spaced.","header":null,"range":null,"order":2,"comment":null},{"name":"clockwise","type":"bool","default":"true","tooltip":"Arranges clockwise if true, counter-clockwise if false.","header":null,"range":null,"order":3,"comment":null},{"name":"rotateChildrenToFaceOutward","type":"bool","default":"false","tooltip":"Rotates each child to face outward from the center, like clock hands.","header":null,"range":null,"order":4,"comment":null}],"src_members":[{"id":"CalculateLayoutInputHorizontal()","sig":"public override void CalculateLayoutInputHorizontal() => base.CalculateLayoutInputHorizontal()","kind":"method","name":"CalculateLayoutInputHorizontal","static":false,"comment":null},{"id":"CalculateLayoutInputVertical()","sig":"public override void CalculateLayoutInputVertical() { }","kind":"method","name":"CalculateLayoutInputVertical","static":false,"comment":null},{"id":"SetLayoutHorizontal()","sig":"public override void SetLayoutHorizontal() => ArrangeChildren()","kind":"method","name":"SetLayoutHorizontal","static":false,"comment":null},{"id":"SetLayoutVertical()","sig":"public override void SetLayoutVertical() => ArrangeChildren()","kind":"method","name":"SetLayoutVertical","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["MathAndUI_Demo"],"entryKind":"tool","status":"published","summary":"Arranges children in a circle or arc. A real LayoutGroup, so it needs no calls.","overview":["Use it instead of a Horizontal or Vertical Layout Group to place children around a circle or along an arc. Unlike the masonry grid this IS a proper layout group, so children snap into place automatically with nothing to call."],"useCases":["A radial or pie menu.","Ability icons around a character portrait.","A clock face or dial."],"params":[{"field":"startAngle","tuning":"0 is up. Worth setting deliberately — a menu that starts at an odd angle looks unintentional."},{"field":"arcDegrees","tuning":"360 spreads evenly all the way round; smaller values make a fan. At exactly 360 the first and last items sit on top of each other unless you account for it."},{"field":"rotateChildrenToFaceOutward","tuning":"Right for a clock face or dial, wrong for icons that must stay upright to be readable."}],"gotchas":[{"title":"A full 360 arc overlaps its ends","body":"The first and last child land at the same angle. Use slightly less than 360, or accept the overlap."}],"seeAlso":["MasonryLayoutGroup","PaginationDots"],"src_uses":[],"src_usedBy":[],"src_extensionPoints":[]},{"id":"aspect-ratio-image-fitter","name":"AspectRatioImageFitter","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/ContentFitters/AspectRatioImageFitter.cs","src_lines":[15,56],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(RawImage)"],"addComponentMenu":"Toolkit/UI/Aspect Ratio Image Fitter"},"src_typeComment":"CSS object-fit for a RawImage: Contain sizes the image to fit entirely within its parent (letterboxed, never cropped); Cover sizes it to fill the parent entirely (cropped, never letterboxed — pair with a Mask/RectMask2D on the parent to actually clip the overflow). Reads the ASSIGNED texture's own aspect ratio automatically — unlike Unity's built-in AspectRatioFitter, which needs that ratio set by hand and has no Cover mode at all.","src_serialized":[{"name":"mode","type":"ImageFitMode","default":"ImageFitMode.Contain","tooltip":null,"header":null,"range":null,"order":0,"comment":null}],"src_members":[{"id":"Refresh()","sig":"public void Refresh()","kind":"method","name":"Refresh","static":false,"comment":"Call this after changing rawImage.texture at runtime, or after the parent container is resized — neither triggers this automatically, since there's no Unity layout-system hook for \"a Texture reference changed.\""}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UIDev_Demo"],"entryKind":"tool","status":"published","summary":"CSS object-fit for a RawImage: Contain letterboxes, Cover crops.","overview":["Contain sizes the image to fit entirely within its parent, letterboxed and never cropped. Cover fills the parent entirely, cropped and never letterboxed — pair that with a Mask or RectMask2D on the parent to actually clip the overflow. It reads the assigned texture's own aspect, so it adapts when the texture changes."],"useCases":["Photo or thumbnail display where images vary in shape.","A full-bleed background that must not distort.","Video or streamed content of unknown aspect."],"params":[{"field":"mode","tuning":"Cover without a mask on the parent overflows visibly. That pairing is not optional."}],"gotchas":[{"title":"Cover needs a mask to look right","body":"It deliberately sizes the image beyond the parent. Without clipping, the overflow just draws over its neighbours."}],"seeAlso":["TextAutoShrinkFitter","MasonryLayoutGroup"],"src_uses":["ImageFitMode"],"src_usedBy":["ImageFitMode"],"src_extensionPoints":[],"parts":[{"id":"image-fit-mode","name":"ImageFitMode","cat":"UI","src_typeKind":"enum","src_ns":"Toolkit.UI","src_file":"UI/ContentFitters/AspectRatioImageFitter.cs","src_lines":[6,6],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"","src_uses":["AspectRatioImageFitter"],"src_usedBy":["AspectRatioImageFitter"],"src_extensionPoints":[],"foldedInto":"aspect-ratio-image-fitter"}]},{"id":"text-auto-shrink-fitter","name":"TextAutoShrinkFitter","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/ContentFitters/TextAutoShrinkFitter.cs","src_lines":[12,34],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(TMP_Text)"],"addComponentMenu":"Toolkit/UI/Text Auto Shrink Fitter"},"src_typeComment":"TMP already supports auto-sizing, but it needs several settings configured together correctly (enableAutoSizing + fontSizeMin/Max + word-wrap + an overflow fallback) to actually behave like \"shrink to fit this box, wrap first, never overflow\" — this is exactly that bundle, in one component with clear tooltips, instead of hunting through the Inspector each time.","src_serialized":[{"name":"minFontSize","type":"float","default":"8f","tooltip":null,"header":null,"range":null,"order":0,"comment":null},{"name":"maxFontSize","type":"float","default":"72f","tooltip":null,"header":null,"range":null,"order":1,"comment":null},{"name":"allowWrapping","type":"bool","default":"true","tooltip":"If true, text wraps across multiple lines before shrinking further. If false, it shrinks toward a single line.","header":null,"range":null,"order":2,"comment":null}],"src_members":[{"id":"Apply()","sig":"public void Apply()","kind":"method","name":"Apply","static":false,"comment":"Public so re-applying after changing minFontSize/maxFontSize/allowWrapping at runtime takes effect immediately instead of waiting for the next Awake."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UIDev_Demo"],"entryKind":"tool","status":"published","summary":"The TMP auto-size settings that actually mean \"wrap first, then shrink, never overflow\", in one component.","overview":["TMP supports auto-sizing, but it takes several settings configured together — auto-sizing on, min and max font size, word wrap, and an overflow fallback — to behave the way people expect. This is exactly that bundle with clear fields."],"useCases":["Item and ability names of varying length in a fixed box.","Localised text where translations are longer than the original.","Any label that must never overflow its container."],"params":[{"field":"minFontSize","tuning":"The real decision. Set too low and long text becomes technically visible and practically unreadable."},{"field":"allowWrapping","tuning":"On means wrap before shrinking, which keeps text larger. Off forces a single line and shrinks harder."}],"gotchas":[{"title":"Shrinking is not always the right answer","body":"For a long name in a narrow strip, scrolling reads better than tiny text — MarqueeText is the alternative."}],"seeAlso":["MarqueeText","AspectRatioImageFitter"],"src_uses":[],"src_usedBy":["MarqueeText"],"src_extensionPoints":[]},{"id":"deferred-layout-rebuilder","name":"DeferredLayoutRebuilder","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/ContentFitters/DeferredLayoutRebuilder.cs","src_lines":[10,31],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Deferred Layout Rebuilder"},"src_typeComment":"Coalesces multiple same-frame rebuild REQUESTS into a single actual rebuild at end-of-frame — e.g. 5 children each independently requesting a rebuild after their own content changed shouldn't force the shared parent to re-lay-out 5 times in one frame.","src_serialized":[],"src_members":[{"id":"RequestRebuild()","sig":"public void RequestRebuild()","kind":"method","name":"RequestRebuild","static":false,"comment":"Call this instead of forcing a rebuild directly — repeated calls within the same frame collapse into one actual rebuild."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UIDev_Demo"],"entryKind":"tool","status":"published","summary":"Coalesces many same-frame rebuild requests into one rebuild at end of frame.","overview":["Five children each requesting a rebuild after their own content changed should not make the shared parent lay out five times in one frame. This collects the requests and does the work once."],"useCases":["A list where many rows update in the same frame.","Several independent components sharing one layout parent.","Reducing layout cost on a busy UI without restructuring it."],"gotchas":[{"title":"It is the opposite of the immediate helper","body":"Use this when many things change and cost is the problem; use the immediate rebuild when you need the size NOW. Mixing them up gives you either a flicker or wasted work."}],"seeAlso":["LayoutRebuildHelper","MasonryLayoutGroup"],"src_uses":["LayoutRebuildHelper"],"src_usedBy":[],"src_extensionPoints":[]},{"id":"layout-rebuild-helper","name":"LayoutRebuildHelper","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/ContentFitters/LayoutRebuildHelper.cs","src_lines":[12,37],"src_base":null,"src_implements":[],"src_static":true,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"Fixes the classic Content Size Fitter \"one-frame-behind\" flicker: Unity defers layout rebuilds to end-of-frame by default, so a runtime content change (new text, an added child) visibly shows the OLD size for one frame before snapping to the new one. ForceRebuildImmediate walks the hierarchy children-first — a nested layout's children must resolve their own sizes before their parent can size correctly around them — and forces the rebuild synchronously instead of waiting.","src_serialized":[],"src_members":[{"id":"ForceRebuildImmediate(RectTransform)","sig":"public static void ForceRebuildImmediate(RectTransform root)","kind":"method","name":"ForceRebuildImmediate","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"published","summary":"Forces an immediate layout rebuild, fixing the Content Size Fitter one-frame flicker.","overview":["Unity defers layout rebuilds to end of frame, so a runtime content change visibly shows the OLD size for one frame before snapping. This walks the hierarchy children-first and rebuilds immediately, which removes the flicker."],"useCases":["Text or children added at runtime inside a Content Size Fitter.","Measuring a layout in the same frame you populated it.","Any visible one-frame pop after a content change."],"gotchas":[{"title":"Children first, and that order matters","body":"Rebuilding a parent before its children measures stale child sizes, which is exactly the bug it exists to avoid."},{"title":"Immediate means expensive","body":"Use it where the flicker is visible, not as a habit. The deferred rebuild exists for a reason."}],"seeAlso":["DeferredLayoutRebuilder","AccordionPanel"],"src_uses":[],"src_usedBy":["DeferredLayoutRebuilder","TimedLine","TimedLineScrollView"],"src_extensionPoints":[]},{"id":"safe-area-handler","name":"SafeAreaHandler","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/SafeArea/SafeAreaHandler.cs","src_lines":[10,46],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(RectTransform)"],"addComponentMenu":"Toolkit/Safe Area Handler"},"src_typeComment":"Drop on a full-stretch RectTransform (usually a direct child of the Canvas) to keep its content inside the device's safe area (notches, rounded corners, home indicator). Re-applies automatically if the screen resolution or orientation changes.","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["MathAndUI_Demo"],"entryKind":"tool","status":"published","summary":"Keeps content inside the device safe area, and re-applies on rotation.","overview":["Drop it on a full-stretch RectTransform, usually a direct child of the Canvas, and it keeps content clear of notches, rounded corners and the home indicator. It re-applies automatically when resolution or orientation changes."],"useCases":["Any phone build with a notch or rounded corners.","Handling rotation without a second layout.","Keeping controls away from the home indicator."],"gotchas":[{"title":"Put it on a container, not on each element","body":"It adjusts the RectTransform it is on. One safe-area container with your UI inside is the pattern; one per element fights itself."},{"title":"The Editor reports a full-screen safe area","body":"So it looks like it does nothing until you run on a device or use a device simulator."}],"seeAlso":["ScreenStackNavigator"],"src_uses":[],"src_usedBy":[],"src_extensionPoints":[]},{"id":"fancy-scroll-view","name":"FancyScrollView","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/FancyScrollView/FancyScrollView.cs","src_lines":[20,165],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(ScrollRect)"],"addComponentMenu":"Toolkit/UI/Fancy Scroll View"},"src_typeComment":"A virtualized, optionally curved scroll view — distinct from the existing lightweight ScrollSnap, which has neither. Only ever instantiates enough cells to cover the visible viewport (+ a small buffer), no matter how large itemCount is, recycling them by re-populating via OnUpdateCell as the index range in view changes — this is the actual point of the tool, for lists too large to just lay out every item at once. Wraps a real ScrollRect for input/inertia rather than reimplementing drag physics.","src_serialized":[{"name":"cellPrefab","type":"RectTransform","default":null,"tooltip":"Template cloned into the pool. Not a GameObject in the scene — instantiate it fresh per pooled slot.","header":null,"range":null,"order":0,"comment":null},{"name":"cellSize","type":"float","default":"100f","tooltip":"Size of one cell along the scroll axis.","header":null,"range":null,"order":1,"comment":null},{"name":"spacing","type":"float","default":"10f","tooltip":null,"header":null,"range":null,"order":2,"comment":null},{"name":"horizontal","type":"bool","default":null,"tooltip":null,"header":null,"range":null,"order":3,"comment":null},{"name":"curve","type":"FancyScrollViewCurve","default":"FancyScrollViewCurve.Linear","tooltip":null,"header":null,"range":null,"order":4,"comment":null},{"name":"bufferCells","type":"int","default":"2","tooltip":"Extra cells kept pooled beyond the visible count, so cells scrolling just offscreen are already instantiated.","header":null,"range":null,"order":5,"comment":null},{"name":"carouselMinScale","type":"float","default":"0.6f","tooltip":"Only used by the Carousel curve — how small the furthest-from-center cells shrink to.","header":null,"range":null,"order":6,"comment":null},{"name":"carouselMinAlpha","type":"float","default":"0.4f","tooltip":"Only used by the Carousel curve — how transparent the furthest-from-center cells become.","header":null,"range":null,"order":7,"comment":null}],"src_members":[{"id":"UnityEvent<int, RectTransform>()","sig":"public UnityEvent<int, RectTransform> OnUpdateCell = new UnityEvent<int, RectTransform>()","kind":"method","name":"UnityEvent","static":false,"comment":"The logical item index, and the pooled cell instance now assigned to show it — bind your data here."},{"id":"PooledCellCount","sig":"public int PooledCellCount => pool.Count","kind":"property","name":"PooledCellCount","static":false,"comment":null},{"id":"SetItemCount(int)","sig":"public void SetItemCount(int count)","kind":"method","name":"SetItemCount","static":false,"comment":"Sets (or changes) the total logical item count — resizes the scroll content to the full virtual length and grows the cell pool if needed (the pool never shrinks below what a previous, larger itemCount already required, since re-instantiating later is wasted work for a size that likely recurs)."}],"src_enumValues":[],"src_selfTest":"UI/FancyScrollView/Editor/FancyScrollViewSelfTest.cs","src_demoScene":["FancyScrollView_Demo"],"entryKind":"tool","status":"published","summary":"Virtualised scroll view with optional curved layouts, instantiating only what is visible.","overview":["Only ever instantiates enough cells to cover the visible viewport plus a small buffer, no matter how large the item count, recycling them as the index range moves. Distinct from the lightweight snap scroll, which does neither virtualisation nor curves."],"useCases":["A list of thousands of items that must scroll smoothly.","A carousel where cells scale and fade toward the edges.","Any list where instantiating every row would be too slow."],"params":[{"field":"cellPrefab","tuning":"A prefab, not a scene object — it is cloned into the pool."},{"field":"bufferCells","tuning":"Extra cells kept beyond the visible count so they are not created mid-scroll. Two or three is usually enough; more just costs memory."},{"field":"curve","tuning":"Carousel mode uses the two carousel settings; the others ignore them."}],"gotchas":[{"title":"Cells are recycled, so never store state on them","body":"The same cell object represents different items as you scroll. All state belongs in your data, applied in the update callback."},{"title":"Uniform cell size","body":"Virtualisation needs to know where each cell is without measuring it. Variable heights are what the masonry layout is for."}],"seeAlso":["ScrollSnap","MasonryLayoutGroup","TimedLineScrollView"],"src_uses":["FancyScrollViewCurve","ScrollSnap"],"src_usedBy":["FancyScrollViewCurve","PaginationDots","TimedLine","TimedLineScrollView"],"src_extensionPoints":[],"parts":[{"id":"fancy-scroll-view-curve","name":"FancyScrollViewCurve","cat":"UI","src_typeKind":"enum","src_ns":"Toolkit.UI","src_file":"UI/FancyScrollView/FancyScrollView.cs","src_lines":[11,11],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"Linear = a plain list, no per-cell scale/alpha variation. Carousel = cells scale down and fade out the further they are from the viewport's center — the classic \"coverflow\"-style effect this tool is named after.","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"Linear = a plain list, no per-cell scale/alpha variation.","src_uses":["FancyScrollView","ScrollSnap"],"src_usedBy":["FancyScrollView"],"src_extensionPoints":[],"foldedInto":"fancy-scroll-view"}]},{"id":"scroll-snap","name":"ScrollSnap","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/ScrollSnap/ScrollSnap.cs","src_lines":[12,145],"src_base":"MonoBehaviour","src_implements":["IBeginDragHandler","IEndDragHandler"],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(ScrollRect)"],"addComponentMenu":"Toolkit/Scroll Snap"},"src_typeComment":"Drop on the same GameObject as a ScrollRect whose Content uses a Horizontal or Vertical Layout Group with evenly-sized items. Dragging works exactly like a normal ScrollRect; releasing the drag eases to the nearest item automatically.","src_serialized":[{"name":"horizontal","type":"bool","default":"true","tooltip":"If true, snaps along the horizontal axis; otherwise vertical.","header":null,"range":null,"order":0,"comment":null},{"name":"snapSpeed","type":"float","default":"10f","tooltip":"How quickly the scroll eases into the snapped position.","header":null,"range":null,"order":1,"comment":null}],"src_members":[{"id":"OnSnapped","sig":"public event System.Action<int> OnSnapped","kind":"event","name":"OnSnapped","static":false,"comment":null},{"id":"ItemCount","sig":"public int ItemCount => scrollRect != null ? scrollRect.content.childCount : 0","kind":"property","name":"ItemCount","static":false,"comment":"For anything that wants to know the page count without reaching into the ScrollRect itself — e.g. Toolkit.UI.PaginationDots.BindToScrollSnap()."},{"id":"OnBeginDrag(PointerEventData)","sig":"public void OnBeginDrag(PointerEventData eventData) => isSnapping = false","kind":"method","name":"OnBeginDrag","static":false,"comment":"Without this, grabbing the scroll again mid-snap would leave LateUpdate still forcibly animating toward the old target every frame, fighting the user's new drag input."},{"id":"OnEndDrag(PointerEventData)","sig":"public void OnEndDrag(PointerEventData eventData)","kind":"method","name":"OnEndDrag","static":false,"comment":null},{"id":"SnapTo(int)","sig":"public void SnapTo(int index)","kind":"method","name":"SnapTo","static":false,"comment":"Call this directly for a \"next/previous\" button instead of dragging."},{"id":"ComputeCenteredNormalizedPosition(int)","sig":"public Vector2 ComputeCenteredNormalizedPosition(int index)","kind":"method","name":"ComputeCenteredNormalizedPosition","static":false,"comment":"Centres the chosen item in the VIEWPORT.  The old version was `index / (itemCount - 1)`, which only centres an item when the viewport is exactly one item wide. With a viewport several items across it just distributes items along the scroll range, so the selected one lands wherever it happens to fall — the \"does not snap the selected to middle\" bug. The correct mapping accounts for the fact that normalized scroll 0..1 spans (content - viewport), not the whole content: take the item's own centre, subtract half a viewport to put it in the middle, then divide by the actual scrollable distance."},{"id":"GetNearestItemIndex()","sig":"public int GetNearestItemIndex()","kind":"method","name":"GetNearestItemIndex","static":false,"comment":"Finds the item whose centre is closest to the VIEWPORT's centre, by measuring actual positions rather than inverting the old normalized-position approximation — which, like SnapTo, only lined up when the viewport was exactly one item wide, so releasing a drag could pick a neighbour of the item actually under the middle."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["MathAndUI_Demo","UIExtras_Demo"],"entryKind":"tool","status":"published","summary":"Adds snap-to-nearest-item to an ordinary ScrollRect.","overview":["Drop it beside a ScrollRect whose content uses a layout group with evenly sized items. Dragging behaves exactly like a normal ScrollRect; releasing eases to the nearest item."],"useCases":["A horizontal page or level selector.","An onboarding carousel.","Any list where items should land centred rather than anywhere."],"params":[{"field":"snapSpeed","tuning":"Too slow feels unresponsive; too fast removes the sense of momentum entirely."}],"gotchas":[{"title":"Items must be evenly sized","body":"The snap target is computed from uniform spacing. Mixed sizes land in the wrong places."}],"seeAlso":["PaginationDots","FancyScrollView","CardCarousel"],"src_uses":["PaginationDots"],"src_usedBy":["FancyScrollView","FancyScrollViewCurve","PaginationDots"],"src_extensionPoints":[]},{"id":"pull-to-refresh","name":"PullToRefresh","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/PullToRefresh/PullToRefresh.cs","src_lines":[40,140],"src_base":"MonoBehaviour","src_implements":["IEndDragHandler"],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(ScrollRect)"],"addComponentMenu":"Toolkit/UI/Pull To Refresh"},"src_typeComment":"Plug-and-play \"pull down at the top of a list to reload\" gesture — the same one Twitter/Instagram/Mail apps use: you're already scrolled to the very top of a list, you keep dragging further down anyway, and if you pull past a threshold and let go, OnRefreshTriggered fires (call your real data-reload code from there). Call EndRefresh() yourself once that finishes, to hide the spinner and snap the list back.  How it actually detects the gesture: Unity's ScrollRect already does a small elastic \"rubber-band\" stretch on its own when you drag past a content boundary, IF Movement Type is set to Elastic (the default) — content.anchoredPosition.y goes slightly POSITIVE while you're doing that at the top, where it's normally 0 or negative. This just reads that existing overshoot on drag-release and reacts to it once it passes pullThreshold — no custom drag physics of its own, just watching a number Unity is already computing.  Three ways to supply the visual indicator, tried in this order: 1) refreshIndicator — a fully hand-built RectTransform (any hierarchy, any animation) for total control. 2) refreshIndicatorPrefab — a prefab/template instantiated once as a child, for a custom animated spinner without needing to pre-place it in this exact scene. 3) refreshIndicatorSprite — the simplest option: just drop in a sprite and this builds a plain Image for you, positioned via indicatorAnchor/indicatorOffset.","src_serialized":[{"name":"pullThreshold","type":"float","default":"80f","tooltip":"How far past the top (in UI units) the user must pull before releasing triggers a refresh.","header":null,"range":null,"order":0,"comment":null},{"name":"refreshIndicator","type":"RectTransform","default":null,"tooltip":"Fully hand-built indicator (any hierarchy). Takes priority over the sprite/prefab options below if assigned.","header":null,"range":null,"order":1,"comment":null},{"name":"refreshIndicatorPrefab","type":"GameObject","default":null,"tooltip":"Instantiated as the indicator if refreshIndicator is empty. Takes priority over refreshIndicatorSprite.","header":null,"range":null,"order":2,"comment":null},{"name":"refreshIndicatorSprite","type":"Sprite","default":null,"tooltip":"Simplest option — auto-builds a plain Image with this sprite if neither refreshIndicator nor refreshIndicatorPrefab is set.","header":null,"range":null,"order":3,"comment":null},{"name":"indicatorAnchor","type":"RefreshIndicatorAnchor","default":"RefreshIndicatorAnchor.Top","tooltip":"Where the auto-built (sprite or prefab) indicator is anchored within this component's own rect. Ignored for a manually-assigned refreshIndicator.","header":null,"range":null,"order":4,"comment":null},{"name":"indicatorSize","type":"Vector2","default":"new Vector2(32f, 32f)","tooltip":null,"header":null,"range":null,"order":5,"comment":null},{"name":"indicatorOffset","type":"Vector2","default":"Vector2.zero","tooltip":"Extra offset applied on top of indicatorAnchor's base position.","header":null,"range":null,"order":6,"comment":null},{"name":"snapBackDuration","type":"float","default":"0.25f","tooltip":null,"header":null,"range":null,"order":7,"comment":null}],"src_members":[{"id":"UnityEvent()","sig":"public UnityEvent OnRefreshTriggered = new UnityEvent()","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"IsRefreshing","sig":"public bool IsRefreshing { get; private set; }","kind":"property","name":"IsRefreshing","static":false,"comment":null},{"id":"OnEndDrag(PointerEventData)","sig":"public void OnEndDrag(PointerEventData eventData)","kind":"method","name":"OnEndDrag","static":false,"comment":null},{"id":"EndRefresh()","sig":"public void EndRefresh()","kind":"method","name":"EndRefresh","static":false,"comment":"Call once your real refresh work (network call, DB query, whatever OnRefreshTriggered kicked off) is done — hides the indicator and eases the list back to its normal resting position."}],"src_enumValues":[],"src_selfTest":"UI/PullToRefresh/Editor/PullToRefreshSelfTest.cs","src_demoScene":["UIExtras_Demo"],"entryKind":"tool","status":"published","summary":"The familiar pull-down-at-the-top-of-a-list gesture, with a configurable indicator.","overview":["The gesture every mobile app uses: already scrolled to the very top, keep dragging down, and releasing past a threshold fires a refresh. Three ways to supply the indicator — a fully hand-built hierarchy, a prefab, or just a sprite it builds an Image from."],"useCases":["Reloading a leaderboard or news feed.","Re-fetching server data in a mobile-style UI.","Any list a player expects to be able to refresh by pulling."],"params":[{"field":"pullThreshold","tuning":"Too small and ordinary over-scroll triggers a refresh by accident."},{"field":"refreshIndicator","tuning":"Takes priority over the prefab and sprite options. Supply only one of the three."}],"gotchas":[{"title":"You must call EndRefresh","body":"It fires the event and waits. If your reload never signals completion, the indicator stays up forever."}],"seeAlso":["ScrollSnap","LoadingBarUI"],"src_uses":["EaseType","RefreshIndicatorAnchor","Tween"],"src_usedBy":["RefreshIndicatorAnchor"],"src_extensionPoints":[],"parts":[{"id":"refresh-indicator-anchor","name":"RefreshIndicatorAnchor","cat":"UI","src_typeKind":"enum","src_ns":"Toolkit.UI","src_file":"UI/PullToRefresh/PullToRefresh.cs","src_lines":[13,18],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"Where the refresh indicator sits within this component's own rect — only used when it's auto-built from refreshIndicatorSprite/refreshIndicatorPrefab below; a manually-assigned refreshIndicator keeps whatever position you gave it in the Inspector.","src_serialized":[],"src_members":[],"src_enumValues":["Top","Center","Bottom"],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"Where the refresh indicator sits within this component's own rect — only used when it's auto-built from...","src_uses":["EaseType","PullToRefresh","Tween"],"src_usedBy":["PullToRefresh"],"src_extensionPoints":[],"foldedInto":"pull-to-refresh"}]},{"id":"timed-line-scroll-view","name":"TimedLineScrollView","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/TimedLineScrollView/TimedLineScrollView.cs","src_lines":[30,228],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(ScrollRect)"],"addComponentMenu":"Toolkit/UI/Timed Line Scroll View"},"src_typeComment":"Plug-and-play auto-scrolling, timeline-synced multi-line text — the \"current line glides into view and lights up while the rest dim\" look popularized by synced song-lyrics displays in music apps, equally useful for a teleprompter script, a subtitle track, or any multi-line text that should auto-advance alongside audio/video/a timeline instead of the viewer manually scrolling.  Distinct from Toolkit.TMPEffects.TMPTimedHighlighter (the SAME timeline-driven idea, different addressing): that one highlights WORDS within one block of text; this one advances between whole LINES, each its own TMP_Text instance, auto-scrolling the container to keep the current one centered — a different enough data model and rendering technique to warrant its own component.","src_serialized":[{"name":"linePrefab","type":"TMP_Text","default":null,"tooltip":"Template cloned once per line. Needs a TMP_Text component.","header":null,"range":null,"order":0,"comment":null},{"name":"lines","type":"List<TimedLine>","default":"new List<TimedLine>()","tooltip":"One entry per line, in ascending startTime order. Populate via the Inspector, SetLines(), SetLinesEvenlySpread(), or LoadLinesFromJson().","header":null,"range":null,"order":1,"comment":null},{"name":"scrollDuration","type":"float","default":"0.4f","tooltip":null,"header":null,"range":null,"order":2,"comment":null},{"name":"scrollEase","type":"EaseType","default":"EaseType.OutQuad","tooltip":null,"header":null,"range":null,"order":3,"comment":null},{"name":"activeColor","type":"Color","default":"Color.white","tooltip":null,"header":null,"range":null,"order":4,"comment":null},{"name":"inactiveColor","type":"Color","default":"new Color(1f, 1f, 1f, 0.35f)","tooltip":null,"header":null,"range":null,"order":5,"comment":null},{"name":"activeFontScale","type":"float","default":"1.15f","tooltip":"The active (current) line's font size multiplies by this — 1 disables the size pop entirely.","header":null,"range":null,"order":6,"comment":null},{"name":"audioSource","type":"AudioSource","default":null,"tooltip":"Optional — if assigned, playback time is read from this automatically every frame instead of needing manual SetPlaybackTime() calls.","header":null,"range":null,"order":7,"comment":null}],"src_members":[{"id":"CurrentLineIndex","sig":"public int CurrentLineIndex => currentIndex","kind":"property","name":"CurrentLineIndex","static":false,"comment":null},{"id":"SetLines(IEnumerable<TimedLine>)","sig":"public void SetLines(IEnumerable<TimedLine> newLines)","kind":"method","name":"SetLines","static":false,"comment":"Replaces the whole line list and rebuilds the displayed line instances — e.g. loading a new song's lyrics or a new script."},{"id":"SetLinesEvenlySpread(IEnumerable<string>, float)","sig":"public void SetLinesEvenlySpread(IEnumerable<string> lineTexts, float totalDuration)","kind":"method","name":"SetLinesEvenlySpread","static":false,"comment":"Quick-start helper for when you don't have real per-line timestamps yet — spreads the given lines evenly across totalDuration. Replace with SetLines()/LoadLinesFromJson() once you have real timing data (e.g. from a synced-lyrics file)."},{"id":"LoadLinesFromJson(string)","sig":"public void LoadLinesFromJson(string json)","kind":"method","name":"LoadLinesFromJson","static":false,"comment":"Accepts either {\"lines\":[{\"text\":\"...\",\"startTime\":0}, ...]} or a bare [...] array (JsonUtility can't parse a top-level array directly, so a bare array is auto-wrapped) — same convention as TMPTimedHighlighter.LoadTimingsFromJson."},{"id":"SetPlaybackTime(float)","sig":"public void SetPlaybackTime(float time)","kind":"method","name":"SetPlaybackTime","static":false,"comment":null},{"id":"ResetScroll()","sig":"public void ResetScroll()","kind":"method","name":"ResetScroll","static":false,"comment":null},{"id":"GetLineIndexAtTime(float)","sig":"public int GetLineIndexAtTime(float time)","kind":"method","name":"GetLineIndexAtTime","static":false,"comment":"Public, pure logic (no TMP dependency) — mirrors TMPTimedHighlighter.GetWordIndexAtTime for the same reason: fully verifiable without needing a real, laid-out TMP font."}],"src_enumValues":[],"src_selfTest":"UI/TimedLineScrollView/Editor/TimedLineScrollViewSelfTest.cs","src_demoScene":["UIExtras_Demo"],"entryKind":"tool","status":"published","summary":"Auto-scrolling multi-line text synced to a timeline, with the current line highlighted.","overview":["The look popularised by synced lyrics in music apps: the current line glides into view and lights up while the rest dim. Equally useful for a teleprompter, a subtitle track, or any multi-line text that should advance itself."],"useCases":["Song lyrics synced to audio.","A teleprompter script.","Subtitles that scroll rather than replacing a single line."],"params":[{"field":"lines","tuning":"In ascending start-time order. Out of order, lines will be skipped rather than sorted."},{"field":"audioSource","tuning":"Assigned, playback time comes from the audio, so the text cannot drift from the sound."},{"field":"activeFontScale","tuning":"Scaling the active line re-flows the list, so large values make neighbours visibly shift."}],"gotchas":[{"title":"Timings are positional, so editing lines invalidates them","body":"Inserting a line shifts everything after it. Regenerate rather than patching."}],"seeAlso":["TMPTimedHighlighter","FancyScrollView"],"src_uses":["EaseType","FancyScrollView","LayoutRebuildHelper","TimedLine","TMPTimedHighlighter","Tween","TweenHandle"],"src_usedBy":["TimedLine"],"src_extensionPoints":[],"parts":[{"id":"timed-line","name":"TimedLine","cat":"UI","src_typeKind":"struct","src_ns":"Toolkit.UI","src_file":"UI/TimedLineScrollView/TimedLineScrollView.cs","src_lines":[12,17],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[{"id":"text","sig":"public string text","kind":"field","name":"text","static":false,"comment":null},{"id":"startTime","sig":"public float startTime","kind":"field","name":"startTime","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"data","status":"skeleton","summary":"","src_uses":["EaseType","FancyScrollView","LayoutRebuildHelper","TimedLineScrollView","TMPTimedHighlighter","Tween","TweenHandle"],"src_usedBy":["TimedLineScrollView"],"src_extensionPoints":[],"foldedInto":"timed-line-scroll-view"}]},{"id":"screen-stack-navigator","name":"ScreenStackNavigator","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/Navigation/ScreenStackNavigator.cs","src_lines":[14,126],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Screen Stack Navigator"},"src_typeComment":"Push/pop panel navigation, like a mobile app's nav stack. Push()/Pop()/Replace()/PopToRoot() manage a stack of screen GameObjects (SetActive'd on/off), with an optional slide transition built on the EXISTING Tween engine. The root screen can never be popped, matching standard mobile nav-stack behavior.","src_serialized":[{"name":"rootScreen","type":"GameObject","default":null,"tooltip":"The first screen shown — must already be active in the scene.","header":null,"range":null,"order":0,"comment":null},{"name":"transitionDuration","type":"float","default":"0.25f","tooltip":"Seconds for the slide transition. 0 = instant, no animation.","header":null,"range":null,"order":1,"comment":null},{"name":"handleBackButton","type":"bool","default":"true","tooltip":"If true, the Escape key (the standard stand-in for Android's hardware back button) pops the current screen.","header":null,"range":null,"order":2,"comment":null}],"src_members":[{"id":"UnityEvent<GameObject>()","sig":"public UnityEvent<GameObject> OnScreenPushed = new UnityEvent<GameObject>()","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"UnityEvent<GameObject>()","sig":"public UnityEvent<GameObject> OnScreenPopped = new UnityEvent<GameObject>()","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"CurrentScreen","sig":"public GameObject CurrentScreen => stack.Count > 0 ? stack[stack.Count - 1] : null","kind":"property","name":"CurrentScreen","static":false,"comment":null},{"id":"Depth","sig":"public int Depth => stack.Count","kind":"property","name":"Depth","static":false,"comment":null},{"id":"SetRootScreen(GameObject)","sig":"public void SetRootScreen(GameObject root)","kind":"method","name":"SetRootScreen","static":false,"comment":"Explicitly (re)configures the root screen — the reliable way to set it up from code, since a plain field assignment after AddComponent() has no guarantee Awake/EnsureInitialized will run again to pick it up. Resets the whole stack back down to just this root."},{"id":"Push(GameObject)","sig":"public void Push(GameObject screen)","kind":"method","name":"Push","static":false,"comment":null},{"id":"Pop()","sig":"public bool Pop()","kind":"method","name":"Pop","static":false,"comment":"Returns false (and does nothing) if there's nothing above the root to pop — the root screen can never be removed this way."},{"id":"PopToRoot()","sig":"public void PopToRoot()","kind":"method","name":"PopToRoot","static":false,"comment":null},{"id":"Replace(GameObject)","sig":"public void Replace(GameObject screen)","kind":"method","name":"Replace","static":false,"comment":"Pops the current screen and pushes a new one in one step — the replaced screen isn't reachable by backing out, unlike a plain Pop()-then-Push()."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UIDev_Demo"],"entryKind":"tool","status":"published","summary":"Push, pop and replace panels like a mobile nav stack, with an optional slide.","overview":["Manages a stack of screen objects with an optional slide transition on the tween engine. The root screen can never be popped, matching how every mobile nav stack behaves, and Escape can act as the Android back button."],"useCases":["Menu flows with a natural back behaviour.","Settings pages nested several levels deep.","Any UI where back should mean \"the previous screen\"."],"params":[{"field":"rootScreen","tuning":"Must already be active in the scene. It is the floor of the stack and cannot be popped."},{"field":"handleBackButton","tuning":"Escape stands in for the Android back button. Turn it off if Escape already means something else."},{"field":"transitionDuration","tuning":"Zero is instant with no animation, which is right for a debug or settings UI."}],"gotchas":[{"title":"Screens are toggled with SetActive","body":"So a screen's Awake runs once but OnEnable runs on every push. State that must reset per visit belongs in OnEnable."},{"title":"It is a stack, not a tab bar","body":"For peer sections the player switches between freely, TabGroup is the right shape."}],"seeAlso":["TabGroup","AsyncSceneLoader","Tween"],"src_uses":["EaseType","Tween"],"src_usedBy":["TabEntry","TabGroup"],"src_extensionPoints":[]},{"id":"tab-group","name":"TabGroup","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/TabGroup/TabGroup.cs","src_lines":[23,71],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Tab Group"},"src_typeComment":"Plug-and-play tab bar: pair each Button with the GameObject it should show, and this handles the click wiring, panel switching, and an active/inactive tint on each tab's own button graphic. Nothing else in this toolkit does a plain horizontal tab bar — ScreenStackNavigator is a full-screen push/pop stack, AccordionPanel collapses vertically in place, CardCarousel swipes — this is the classic \"click a tab, swap the panel below it\" pattern none of those cover.","src_serialized":[{"name":"tabs","type":"TabEntry[]","default":null,"tooltip":null,"header":null,"range":null,"order":0,"comment":null},{"name":"activeColor","type":"Color","default":"Color.white","tooltip":null,"header":null,"range":null,"order":1,"comment":null},{"name":"inactiveColor","type":"Color","default":"new Color(0.6f, 0.6f, 0.6f)","tooltip":null,"header":null,"range":null,"order":2,"comment":null},{"name":"startIndex","type":"int","default":null,"tooltip":null,"header":null,"range":null,"order":3,"comment":null}],"src_members":[{"id":"UnityEvent<int>()","sig":"public UnityEvent<int> OnTabChanged = new UnityEvent<int>()","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"CurrentIndex","sig":"public int CurrentIndex { get; private set; } = -1","kind":"property","name":"CurrentIndex","static":false,"comment":null},{"id":"TabCount","sig":"public int TabCount => tabs != null ? tabs.Length : 0","kind":"property","name":"TabCount","static":false,"comment":null},{"id":"SetTabs(TabEntry[])","sig":"public void SetTabs(TabEntry[] newTabs)","kind":"method","name":"SetTabs","static":false,"comment":"For configuring tabs from code (a dynamically-built tab set) instead of the Inspector array — mirrors the Set*() pattern this toolkit already uses elsewhere (e.g. ScreenStackNavigator.SetRootScreen) for components more naturally wired at runtime than authored by hand."},{"id":"SelectTab(int)","sig":"public void SelectTab(int index)","kind":"method","name":"SelectTab","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":"UI/TabGroup/Editor/TabGroupSelfTest.cs","src_demoScene":["UIExtras_Demo"],"entryKind":"tool","status":"published","summary":"A plain tab bar: pair each button with the panel it shows, and it handles the rest.","overview":["Pair each Button with the GameObject it should show and it handles the click wiring, panel switching and an active/inactive tint on each tab's own graphic. Nothing else in the toolkit does a plain tab bar — the navigator is a full-screen push and pop, which is a different shape."],"useCases":["Inventory, equipment and stats as tabs on one screen.","Settings categories switched in place.","Any peer sections where back does not mean anything."],"params":[{"field":"startIndex","tuning":"Which tab is selected on enable. Out of range and nothing is selected, which looks like a broken screen."}],"gotchas":[{"title":"It tints the button's own graphic","body":"A tab whose Button has no target graphic shows no active state, even though switching works."}],"seeAlso":["ScreenStackNavigator","AccordionPanel"],"src_uses":["AccordionPanel","CardCarousel","ScreenStackNavigator","TabEntry"],"src_usedBy":["TabEntry"],"src_extensionPoints":[],"parts":[{"id":"tab-entry","name":"TabEntry","cat":"UI","src_typeKind":"struct","src_ns":"Toolkit.UI","src_file":"UI/TabGroup/TabGroup.cs","src_lines":[9,15],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[{"id":"button","sig":"public Button button","kind":"field","name":"button","static":false,"comment":null},{"id":"panel","sig":"public GameObject panel","kind":"field","name":"panel","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"data","status":"skeleton","summary":"","src_uses":["AccordionPanel","CardCarousel","ScreenStackNavigator","TabGroup"],"src_usedBy":["TabGroup"],"src_extensionPoints":[],"foldedInto":"tab-group"}]},{"id":"pagination-dots","name":"PaginationDots","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/PaginationDots/PaginationDots.cs","src_lines":[19,141],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Pagination Dots"},"src_typeComment":"Plug-and-play pagination dots (the row of dots under a carousel/swiper showing which page you're on). Fully usable standalone (call Setup()/SetCurrentIndex() yourself from any paging system), but built specifically so it \"just works\" with this toolkit's own paged UI: BindToCardCarousel() and BindToScrollSnap() wire everything in one call — dot count, click-to-jump, and staying in sync as the page changes from either end (a drag, a Next()/Previous() call, or clicking a dot).  Deliberately NOT offering a BindToFancyScrollView(): FancyScrollView is a continuously virtualized scroll (it tracks a scroll OFFSET, not a discrete \"current page\" index) — there's no clean page concept to put a dot on. If you need dots with FancyScrollView, drive SetCurrentIndex() yourself from whatever page boundary makes sense for your content.","src_serialized":[{"name":"dotPrefab","type":"RectTransform","default":null,"tooltip":"Optional custom dot template (needs an Image; add a Button on it too if you want click-to-jump). Leave empty to auto-build plain colored square dots.","header":null,"range":null,"order":0,"comment":null},{"name":"dotSpacing","type":"float","default":"24f","tooltip":null,"header":null,"range":null,"order":1,"comment":null},{"name":"dotSize","type":"float","default":"12f","tooltip":null,"header":null,"range":null,"order":2,"comment":null},{"name":"activeColor","type":"Color","default":"Color.white","tooltip":null,"header":null,"range":null,"order":3,"comment":null},{"name":"inactiveColor","type":"Color","default":"new Color(1f, 1f, 1f, 0.35f)","tooltip":null,"header":null,"range":null,"order":4,"comment":null},{"name":"clickable","type":"bool","default":"true","tooltip":"If true, clicking a dot fires OnDotClicked so you (or a Bind* call) can jump straight to that page.","header":null,"range":null,"order":5,"comment":null}],"src_members":[{"id":"UnityEvent<int>()","sig":"public UnityEvent<int> OnDotClicked = new UnityEvent<int>()","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"CurrentIndex","sig":"public int CurrentIndex { get; private set; }","kind":"property","name":"CurrentIndex","static":false,"comment":null},{"id":"PageCount","sig":"public int PageCount { get; private set; }","kind":"property","name":"PageCount","static":false,"comment":null},{"id":"Setup(int, int)","sig":"public void Setup(int pageCount, int startIndex = 0)","kind":"method","name":"Setup","static":false,"comment":"Builds (or rebuilds) one dot per page, centered on this GameObject."},{"id":"SetCurrentIndex(int)","sig":"public void SetCurrentIndex(int index)","kind":"method","name":"SetCurrentIndex","static":false,"comment":null},{"id":"BindToCardCarousel(CardCarousel)","sig":"public void BindToCardCarousel(CardCarousel carousel)","kind":"method","name":"BindToCardCarousel","static":false,"comment":"One-call setup for the exact pairing this tool was asked to support: dot count and starting page come straight from the carousel, dots stay in sync with Next()/Previous()/drag, and clicking a dot calls the carousel's own GoTo()."},{"id":"BindToScrollSnap(ScrollSnap)","sig":"public void BindToScrollSnap(ScrollSnap scrollSnap)","kind":"method","name":"BindToScrollSnap","static":false,"comment":"Same idea for ScrollSnap — ItemCount reads its Content's real child count, OnSnapped keeps dots in sync with drag-to-snap, and clicking a dot calls SnapTo() directly."}],"src_enumValues":[],"src_selfTest":"UI/PaginationDots/Editor/PaginationDotsSelfTest.cs","src_demoScene":["UIExtras_Demo"],"entryKind":"tool","status":"published","summary":"The row of dots under a carousel, bindable to the toolkit's own paged views.","overview":["Usable standalone by calling Setup and SetCurrentIndex from any paging system, and built to bind directly to the toolkit's own card carousel and scroll snap so it just works with either."],"useCases":["Page indicators under an onboarding carousel.","Showing position in a card deck.","Clickable dots for jumping directly to a page."],"params":[{"field":"dotPrefab","tuning":"Optional. A custom dot needs an Image, and a Button too if you want it clickable."},{"field":"clickable","tuning":"Firing the event is all it does — you still connect that to whatever should change page."}],"gotchas":[{"title":"Binding does not survive the source changing page count","body":"Call Setup again if the number of pages changes at runtime."}],"seeAlso":["CardCarousel","ScrollSnap"],"src_uses":["CardCarousel","FancyScrollView","ScrollSnap"],"src_usedBy":["ScrollSnap"],"src_extensionPoints":[]},{"id":"async-scene-loader","name":"AsyncSceneLoader","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/SceneLoader/AsyncSceneLoader.cs","src_lines":[13,56],"src_base":"Singleton<AsyncSceneLoader>","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Async Scene Loader"},"src_typeComment":"Singleton async scene loader: call AsyncSceneLoader.Instance.LoadScene(\"Level2\") and wire OnProgress to a loading-bar Image.fillAmount. Enforces a minimum display time so a loading screen that would finish in one frame doesn't just flash — genuinely fast loads still show for at least that long.","src_serialized":[{"name":"minimumDisplayTime","type":"float","default":"0.5f","tooltip":"The loading screen stays up at least this long, even if the scene loads faster.","header":null,"range":null,"order":0,"comment":null}],"src_members":[{"id":"UnityEvent()","sig":"public UnityEvent OnLoadStarted = new UnityEvent()","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"UnityEvent<float>()","sig":"public UnityEvent<float> OnProgress = new UnityEvent<float>(); // 0..1","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"UnityEvent()","sig":"public UnityEvent OnLoadCompleted = new UnityEvent()","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"IsLoading","sig":"public bool IsLoading { get; private set; }","kind":"property","name":"IsLoading","static":false,"comment":null},{"id":"LoadScene(string)","sig":"public void LoadScene(string sceneName)","kind":"method","name":"LoadScene","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UIPolish_Demo"],"entryKind":"tool","status":"published","summary":"Async scene loading with progress, and a minimum display time so the loading screen cannot flash.","overview":["Call LoadScene and wire the progress event to a bar. It enforces a minimum display time, so a load that would finish in one frame does not flash the loading screen — a genuinely fast load still shows for at least that long."],"useCases":["A loading screen between levels.","Showing real progress rather than a fake bar.","Avoiding the jarring one-frame flash on fast loads."],"params":[{"field":"minimumDisplayTime","tuning":"Long enough to read, short enough not to annoy. Around a second is typical."}],"gotchas":[{"title":"Unity's progress stops at 0.9 until activation","body":"AsyncOperation.progress caps there when allowSceneActivation is false. A bar driven straight from it appears to stall just before finishing — which is why this one normalises it."}],"seeAlso":["LoadingBarUI","FadeManager"],"src_uses":["Singleton<T>"],"src_usedBy":["LoadingBarUI"],"src_extensionPoints":[]},{"id":"drag-and-drop","name":"DragAndDrop","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/DragAndDrop/DraggableItem.cs","src_lines":[13,105],"src_base":"MonoBehaviour","src_implements":["IBeginDragHandler","IDragHandler","IEndDragHandler"],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(RectTransform)"],"addComponentMenu":"Toolkit/UI/Draggable Item"},"src_typeComment":"Reusable draggable UI item — not tied to any one specific system (inventory, kiosk menu, puzzle piece). Drops onto whichever DropZone is under the pointer on release, if any accepts it; otherwise snaps back to where it started. Reparents to the root Canvas while dragging so it draws on top of any sibling UI.","src_serialized":[{"name":"itemTag","type":"string","default":null,"tooltip":"Optional tag a DropZone can filter on via its acceptedTags list. Leave blank to be accepted everywhere unfiltered.","header":null,"range":null,"order":0,"comment":null},{"name":"draggingAlpha","type":"float","default":"0.7f","tooltip":"CanvasGroup alpha while being dragged, so it visually reads as 'lifted'.","header":null,"range":null,"order":1,"comment":null}],"src_members":[{"id":"ItemTag","sig":"public string ItemTag => itemTag","kind":"property","name":"ItemTag","static":false,"comment":null},{"id":"UnityEvent<DropZone>()","sig":"public UnityEvent<DropZone> OnDropped = new UnityEvent<DropZone>()","kind":"method","name":"UnityEvent","static":false,"comment":"Fires on every drag end — with the DropZone it landed on, or null if it snapped back to origin."},{"id":"OnBeginDrag(PointerEventData)","sig":"public void OnBeginDrag(PointerEventData eventData)","kind":"method","name":"OnBeginDrag","static":false,"comment":null},{"id":"OnDrag(PointerEventData)","sig":"public void OnDrag(PointerEventData eventData)","kind":"method","name":"OnDrag","static":false,"comment":null},{"id":"OnEndDrag(PointerEventData)","sig":"public void OnEndDrag(PointerEventData eventData)","kind":"method","name":"OnEndDrag","static":false,"comment":null},{"id":"ReturnToOrigin()","sig":"public void ReturnToOrigin()","kind":"method","name":"ReturnToOrigin","static":false,"comment":"Public so a DropZone (or anything else) can send this item back where it came from — e.g. a zone that turns out to be full and rejects the drop after accepting the raycast hit."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UIDev_Demo"],"entryKind":"tool","status":"published","summary":"A reusable draggable UI item that drops onto a zone or snaps back.","overview":["Not tied to any one system — inventory, kiosk menu, puzzle piece. On release it drops onto whichever DropZone is under the pointer if one accepts it, and otherwise snaps back to where it started. It reparents to the root Canvas while dragging so it draws above sibling panels."],"useCases":["Dragging items between inventory slots.","A puzzle where pieces are dragged into place.","Reordering a list by dragging."],"params":[{"field":"itemTag","tuning":"What a zone filters on. Leave empty and every zone with a filter rejects it."},{"field":"draggingAlpha","tuning":"Below 1 so the item reads as \"in transit\" rather than placed."}],"gotchas":[{"title":"Reparenting to the Canvas changes its layout context","body":"That is what stops it being clipped by a panel, and it means an item inside a layout group will not keep its layout size while dragged."},{"title":"It goes through the EventSystem, not physics","body":"This is UI dragging. For picking real scene colliders, ClickToSelect is the 3D equivalent."}],"seeAlso":["DropZone","ClickToSelect"],"src_uses":["DropZone"],"src_usedBy":["CardCarousel","ClickToSelect","DropZone"],"src_extensionPoints":[],"isSystem":true,"systemOf":"DraggableItem","systemPrimaryId":"draggable-item","systemSections":[{"title":"Supporting scripts","entries":[{"id":"drop-zone","name":"DropZone","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/DragAndDrop/DropZone.cs","src_lines":[9,42],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Drop Zone"},"src_typeComment":"Pairs with DraggableItem — a target region that accepts (or rejects, via acceptedTags) a dropped item.","src_serialized":[{"name":"acceptedTags","type":"List<string>","default":"new List<string>()","tooltip":"If non-empty, only DraggableItems whose itemTag is in this list are accepted. Leave empty to accept any item.","header":null,"range":null,"order":0,"comment":null},{"name":"reparentOnDrop","type":"bool","default":"true","tooltip":"If true, a dropped item is reparented under this zone and snapped to its center.","header":null,"range":null,"order":1,"comment":null}],"src_members":[{"id":"UnityEvent<DraggableItem>()","sig":"public UnityEvent<DraggableItem> OnItemDropped = new UnityEvent<DraggableItem>()","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"SetAcceptedTags(IEnumerable<string>)","sig":"public void SetAcceptedTags(IEnumerable<string> tags)","kind":"method","name":"SetAcceptedTags","static":false,"comment":"Public setter for configuring this from code (e.g. spawned/wired at runtime) — a plain string List has no SerializedProperty ObjectReference path the way an object-array field does, so this is the supported way to set it outside the Inspector."},{"id":"CanAccept(DraggableItem)","sig":"public bool CanAccept(DraggableItem item)","kind":"method","name":"CanAccept","static":false,"comment":null},{"id":"Drop(DraggableItem)","sig":"public void Drop(DraggableItem item)","kind":"method","name":"Drop","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UIDev_Demo"],"entryKind":"tool","status":"published","summary":"A target region that accepts or rejects a dragged item, optionally reparenting it.","overview":["The other half of dragging. It can filter by tag, so a weapon slot rejects a potion, and can reparent the dropped item so it stays where it landed."],"useCases":["Equipment slots accepting only the right item type.","A bin or sell zone.","Puzzle targets that accept one specific piece."],"params":[{"field":"acceptedTags","tuning":"Empty means accept anything. A typo here rejects everything, silently."},{"field":"reparentOnDrop","tuning":"On, the item becomes a child and stays. Off, it returns to its origin even though the drop succeeded — which is what you want when the zone is a command rather than a container."}],"gotchas":[{"title":"It needs to be raycastable","body":"A zone with no raycast target graphic is never under the pointer, so drops always fail."}],"seeAlso":["DraggableItem"],"src_uses":["DraggableItem"],"src_usedBy":["DraggableItem"],"src_extensionPoints":[]}]}]},{"id":"draggable-ui-panel","name":"DraggableUIPanel","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/DraggablePanel/DraggableUIPanel.cs","src_lines":[9,43],"src_base":"MonoBehaviour","src_implements":["IBeginDragHandler","IDragHandler"],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Draggable UI Panel"},"src_typeComment":"Drop on a UI panel (typically a \"title bar\" child, but works directly on the panel too) to make it drag-to-move — movable HUD elements, debug/inspector-style floating windows.","src_serialized":[{"name":"panelToMove","type":"RectTransform","default":null,"tooltip":"The panel that actually moves. Defaults to this object's own RectTransform if left empty — assign a different one if this script sits on a title-bar child instead of the panel itself.","header":null,"range":null,"order":0,"comment":null},{"name":"clampToParent","type":"bool","default":"true","tooltip":"Keeps the panel fully within its parent's bounds while dragging.","header":null,"range":null,"order":1,"comment":null}],"src_members":[{"id":"OnBeginDrag(PointerEventData)","sig":"public void OnBeginDrag(PointerEventData eventData) { }","kind":"method","name":"OnBeginDrag","static":false,"comment":null},{"id":"OnDrag(PointerEventData)","sig":"public void OnDrag(PointerEventData eventData)","kind":"method","name":"OnDrag","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UIPolish_Demo"],"entryKind":"tool","status":"published","summary":"Makes a panel drag-to-move, optionally clamped to its parent.","overview":["Drop it on a panel, or on a title-bar child, to make it movable — for repositionable HUD elements and floating debug windows."],"useCases":["A debug or inspector window the developer can move.","HUD elements the player can reposition.","A floating tool palette."],"params":[{"field":"panelToMove","tuning":"Defaults to this object's own RectTransform. Set it to the panel root when the component lives on a title bar."},{"field":"clampToParent","tuning":"Off, a panel can be dragged completely off screen and become unreachable."}],"gotchas":[{"title":"Dragging fights a layout group","body":"A panel under a layout group has its position overwritten every rebuild. Drag panels that are not laid out."}],"seeAlso":["DraggableItem"],"src_uses":[],"src_usedBy":["VirtualKeyboard"],"src_extensionPoints":[]},{"id":"hold-to-confirm-button","name":"HoldToConfirmButton","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/HoldToConfirmButton/HoldToConfirmButton.cs","src_lines":[14,70],"src_base":"MonoBehaviour","src_implements":["IPointerDownHandler","IPointerUpHandler","IPointerExitHandler"],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Hold To Confirm Button"},"src_typeComment":"Plug-and-play \"hold to confirm\" button — press and hold for holdDuration seconds to fire OnConfirmed, releasing early fires OnHoldCancelled instead. The classic \"hold to delete/reset\" pattern that protects against an accidental single tap doing something destructive. Purely logic + timing — the visual fill is optional and decoupled: assign an existing Toolkit.UI.RadialProgressBar (or anything with a SetProgress(0..1) method) to progressVisual, or leave it empty and drive your own feedback from OnHoldProgress instead.","src_serialized":[{"name":"holdDuration","type":"float","default":"1f","tooltip":null,"header":null,"range":null,"order":0,"comment":null},{"name":"progressVisual","type":"RadialProgressBar","default":null,"tooltip":"Optional — shows hold progress. Leave empty if you don't need a visual fill, or wire your own via OnHoldProgress.","header":null,"range":null,"order":1,"comment":null},{"name":"resetOnRelease","type":"bool","default":"true","tooltip":"If true, releasing early resets progress back to 0; if false, a cancelled hold resumes from where it left off next time.","header":null,"range":null,"order":2,"comment":null}],"src_members":[{"id":"UnityEvent()","sig":"public UnityEvent OnConfirmed = new UnityEvent()","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"UnityEvent()","sig":"public UnityEvent OnHoldCancelled = new UnityEvent()","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"UnityEvent<float>()","sig":"public UnityEvent<float> OnHoldProgress = new UnityEvent<float>(); // 0..1, fires every frame while held","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"NormalizedProgress","sig":"public float NormalizedProgress => holdDuration > 0f ? Mathf.Clamp01(heldTime / holdDuration) : 0f","kind":"property","name":"NormalizedProgress","static":false,"comment":null},{"id":"OnPointerDown(PointerEventData)","sig":"public void OnPointerDown(PointerEventData eventData)","kind":"method","name":"OnPointerDown","static":false,"comment":null},{"id":"OnPointerUp(PointerEventData)","sig":"public void OnPointerUp(PointerEventData eventData) => CancelHold()","kind":"method","name":"OnPointerUp","static":false,"comment":null},{"id":"OnPointerExit(PointerEventData)","sig":"public void OnPointerExit(PointerEventData eventData) => CancelHold()","kind":"method","name":"OnPointerExit","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":"UI/HoldToConfirmButton/Editor/HoldToConfirmButtonSelfTest.cs","src_demoScene":["UIExtras_Demo"],"entryKind":"tool","status":"published","summary":"Press and hold to confirm, releasing early cancels. Logic only, visuals are yours.","overview":["The classic hold-to-delete pattern that protects against an accidental tap doing something destructive. Purely logic and timing — the visual is an optional progress object, so you can use a ring, a bar or nothing."],"useCases":["Delete save, reset progress or any destructive action.","A hold-to-skip cutscene control.","Confirming on a touchscreen where mis-taps are common."],"params":[{"field":"holdDuration","tuning":"Long enough to be deliberate, short enough not to feel broken. Around a second is typical."},{"field":"resetOnRelease","tuning":"Off keeps partial progress, so a player can build up across several presses — which usually defeats the point of the guard."}],"gotchas":[{"title":"Pointer exit cancels too","body":"Dragging off the button while holding counts as releasing, which is the conventional behaviour and surprising if you expected it to keep counting."}],"seeAlso":["RadialProgressBar","ModalDialog"],"src_uses":["RadialProgressBar"],"src_usedBy":[],"src_extensionPoints":[]},{"id":"toggle-switch","name":"ToggleSwitch","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/ToggleSwitch/ToggleSwitch.cs","src_lines":[14,63],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(Toggle)"],"addComponentMenu":"Toolkit/UI/Toggle Switch"},"src_typeComment":"Plug-and-play iOS-style animated toggle switch — built on top of Unity's OWN Toggle component rather than reimplementing click/keyboard/gamepad-navigation handling from scratch, so all of that keeps working exactly as it does on any other Toggle. This just adds the sliding-handle + background-color visual on top, since Unity's stock Toggle only ships with a plain checkbox look.","src_serialized":[{"name":"handle","type":"RectTransform","default":null,"tooltip":"The knob that slides between the off/on positions. Auto-found among children if left empty.","header":null,"range":null,"order":0,"comment":null},{"name":"background","type":"Image","default":null,"tooltip":"The track behind the handle, tinted per state. Auto-found on this GameObject if left empty.","header":null,"range":null,"order":1,"comment":null},{"name":"animationDuration","type":"float","default":"0.15f","tooltip":null,"header":null,"range":null,"order":2,"comment":null},{"name":"onColor","type":"Color","default":"new Color(0.25f, 0.75f, 0.35f)","tooltip":null,"header":null,"range":null,"order":3,"comment":null},{"name":"offColor","type":"Color","default":"new Color(0.6f, 0.6f, 0.6f)","tooltip":null,"header":null,"range":null,"order":4,"comment":null},{"name":"handleOffX","type":"float","default":"-10f","tooltip":"The handle's local X position when off vs on, in UI units.","header":null,"range":null,"order":5,"comment":null},{"name":"handleOnX","type":"float","default":"10f","tooltip":null,"header":null,"range":null,"order":6,"comment":null}],"src_members":[{"id":"ApplyVisualState(bool, bool)","sig":"public void ApplyVisualState(bool isOn, bool instant)","kind":"method","name":"ApplyVisualState","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":"UI/ToggleSwitch/Editor/ToggleSwitchSelfTest.cs","src_demoScene":["UIExtras_Demo"],"entryKind":"tool","status":"published","summary":"An iOS-style animated switch built on Unity's own Toggle, so navigation still works.","overview":["Built ON TOP of Unity's Toggle rather than reimplementing click, keyboard and gamepad navigation — so all of that keeps working exactly as on any other Toggle. This adds only the sliding handle and the background colour animation."],"useCases":["Settings screens with on/off options.","A mobile-styled UI where a checkbox looks wrong.","Any toggle that should still be gamepad-navigable."],"params":[{"field":"handleOffX","tuning":"The handle's local X in each state, in UI units. These are positions, not offsets, so they depend on your track size."},{"field":"animationDuration","tuning":"Short. A switch that takes noticeable time feels laggy rather than smooth."}],"gotchas":[{"title":"The Toggle is still the source of truth","body":"Read and write the Toggle's isOn, not this component. It only draws the state."}],"seeAlso":["SettingsManager"],"src_uses":["EaseType","Tween"],"src_usedBy":[],"src_extensionPoints":[]},{"id":"toast-notification","name":"ToastNotification","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/Toast/ToastNotification.cs","src_lines":[12,72],"src_base":"Singleton<ToastNotification>","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Toast Notification"},"src_typeComment":"Singleton toast queue: call ToastNotification.Instance.Show(\"message\") from anywhere. Messages queue up and display one at a time so a burst of calls doesn't overlap into unreadable stacked text.","src_serialized":[{"name":"panel","type":"RectTransform","default":null,"tooltip":"The panel shown/hidden per toast.","header":null,"range":null,"order":0,"comment":null},{"name":"label","type":"TMP_Text","default":null,"tooltip":"Text component the toast message is written to.","header":null,"range":null,"order":1,"comment":null},{"name":"displayDuration","type":"float","default":"2f","tooltip":"How long each toast stays visible before the next one shows.","header":null,"range":null,"order":2,"comment":null}],"src_members":[{"id":"Show(string)","sig":"public void Show(string message)","kind":"method","name":"Show","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UIPolish_Demo"],"entryKind":"tool","status":"published","summary":"Singleton toast queue: call Show(\"message\") from anywhere and messages display one at a time.","overview":["A short status message that appears, sits for a moment and goes away — \"Saved\", \"Not enough gold\", \"Checkpoint reached\". Call it from anywhere without holding a reference, and a burst of calls queues instead of stacking into unreadable overlapping text."],"useCases":["Confirming an action succeeded without interrupting the player with a dialog.","Surfacing a soft failure — a purchase you cannot afford, an inventory that is full.","Debug feedback during development, from systems that have no UI of their own."],"params":[{"field":"panel","why":"The panel shown and hidden for each toast.","tuning":"This component can sit on the panel itself — that is the normal setup and it is safe, because hiding is done with a CanvasGroup rather than by deactivating the object."},{"field":"label","why":"The TMP_Text the message is written into.","tuning":"Left unwired, toasts still queue and time out correctly — you just never see the text. Nothing errors."},{"field":"displayDuration","why":"Seconds each toast stays up before the next one shows.","tuning":"This is per message, so a queue of five at the default 2s takes 10 seconds to drain. Keep it short if bursts are likely."}],"usage":{"code":"ToastNotification.Instance.Show(\"Checkpoint reached\");\nToastNotification.Instance.Show(\"Not enough gold\");   // queues behind the first","codeNote":"No reference needed and no null check — Singleton<T>.Instance finds the one in the scene."},"gotchas":[{"title":"Never hide the panel by deactivating its GameObject","body":"If this component sits on the panel it hides, deactivating that object breaks it twice over: Singleton<T>.Instance uses FindObjectOfType, which skips inactive objects, so Instance silently creates a SECOND empty ToastNotification with nothing wired and every Show() does nothing; and StartCoroutine cannot run on an inactive GameObject, so the queue never processes. It hides via a CanvasGroup for exactly this reason. This was a real bug, not a hypothetical."},{"title":"The queue is drained by a coroutine, so it needs Play mode","body":"Show() outside Play mode enqueues the message and nothing more — the coroutine that displays it never runs."},{"title":"Waiting is scaled time","body":"It waits with WaitForSeconds, so a toast shown while the game is paused with Time.timeScale = 0 stays up indefinitely. Pause menus that need toasts want an unscaled wait instead."}],"seeAlso":["ModalDialog","Singleton<T>","TooltipSystem"],"src_uses":["Singleton<T>"],"src_usedBy":["ModalDialog","Singleton<T>","VirtualKeyboard"],"src_extensionPoints":[]},{"id":"modal-dialog","name":"ModalDialog","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/Modal/ModalDialog.cs","src_lines":[12,75],"src_base":"Singleton<ModalDialog>","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Modal Dialog"},"src_typeComment":"Singleton generic confirm dialog: call ModalDialog.Instance.Show(\"Delete save?\", onConfirm, onCancel) instead of hand-building a new Yes/No popup every time you need one.","src_serialized":[{"name":"panel","type":"RectTransform","default":null,"tooltip":null,"header":null,"range":null,"order":0,"comment":null},{"name":"messageLabel","type":"TMP_Text","default":null,"tooltip":null,"header":null,"range":null,"order":1,"comment":null},{"name":"confirmButton","type":"Button","default":null,"tooltip":null,"header":null,"range":null,"order":2,"comment":null},{"name":"confirmLabel","type":"TMP_Text","default":null,"tooltip":null,"header":null,"range":null,"order":3,"comment":null},{"name":"cancelButton","type":"Button","default":null,"tooltip":null,"header":null,"range":null,"order":4,"comment":null},{"name":"cancelLabel","type":"TMP_Text","default":null,"tooltip":null,"header":null,"range":null,"order":5,"comment":null}],"src_members":[{"id":"Show(string, Action, Action, string, string)","sig":"public void Show(string message, Action onConfirm, Action onCancel = null, string confirmText = \"OK\", string cancelText = \"Cancel\")","kind":"method","name":"Show","static":false,"comment":"onCancel may be null — the Cancel button just closes the dialog with no callback in that case."},{"id":"Hide()","sig":"public void Hide() => SetPanelVisible(false)","kind":"method","name":"Hide","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UIPolish_Demo"],"entryKind":"tool","status":"published","summary":"One reusable confirm dialog: call Show with a message and callbacks.","overview":["A singleton yes/no dialog, so you stop hand-building a new popup every time something needs confirming."],"useCases":["Confirming a destructive action.","A quit or return-to-menu prompt.","Any yes/no question that does not deserve its own screen."],"gotchas":[{"title":"It must never hide by deactivating its own GameObject","body":"A Singleton finds its instance with FindObjectOfType, which skips inactive objects — so deactivating itself makes Instance silently create a second, empty one. It hides with a CanvasGroup for exactly this reason. This was a real bug in this toolkit, not a hypothetical."},{"title":"One dialog at a time","body":"Showing a second while one is open replaces the first, and the first's callbacks never fire."}],"seeAlso":["ToastNotification","Singleton<T>","HoldToConfirmButton"],"src_uses":["Singleton<T>","ToastNotification"],"src_usedBy":["Singleton<T>","VirtualKeyboard"],"src_extensionPoints":[]},{"id":"tooltips","name":"Tooltips","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/Tooltip/TooltipSystem.cs","src_lines":[11,60],"src_base":"Singleton<TooltipSystem>","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/Tooltip System"},"src_typeComment":"Singleton that shows/hides a single tooltip panel following the cursor. Add one to your UI Canvas, assign the panel + text, then call TooltipSystem.Instance.Show(\"text\") from anywhere — or just add TooltipTrigger to individual UI elements for zero-code hover tooltips.","src_serialized":[{"name":"panel","type":"RectTransform","default":null,"tooltip":"The panel containing the tooltip background + text, toggled on/off.","header":null,"range":null,"order":0,"comment":null},{"name":"label","type":"TMP_Text","default":null,"tooltip":"Text component the tooltip message is written to.","header":null,"range":null,"order":1,"comment":null},{"name":"cursorOffset","type":"Vector2","default":"new Vector2(16f, -16f)","tooltip":"Offset from the cursor in screen pixels.","header":null,"range":null,"order":2,"comment":null}],"src_members":[{"id":"Show(string)","sig":"public void Show(string text)","kind":"method","name":"Show","static":false,"comment":null},{"id":"Hide()","sig":"public void Hide()","kind":"method","name":"Hide","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["MathAndUI_Demo"],"entryKind":"tool","status":"published","summary":"One tooltip panel that follows the cursor, shown from anywhere.","overview":["Add one to your Canvas, assign the panel and text, then call Show from anywhere — or just add a trigger to individual elements for zero-code hover tooltips."],"useCases":["Hover descriptions on items and abilities.","Explaining a setting without cluttering the screen.","Contextual help on an editor-style UI."],"params":[{"field":"cursorOffset","tuning":"In screen pixels. Enough that the cursor does not sit on top of the text, and not so much that the tooltip drifts off screen at the edges."}],"gotchas":[{"title":"It does not keep itself on screen","body":"Near a screen edge the panel can extend past it. Clamping is not built in."}],"seeAlso":["TooltipTrigger","ToastNotification"],"src_uses":["Singleton<T>","TooltipTrigger"],"src_usedBy":["TooltipTrigger"],"src_extensionPoints":[],"isSystem":true,"systemOf":"TooltipSystem","systemPrimaryId":"tooltip-system","systemSections":[{"title":"Supporting scripts","entries":[{"id":"tooltip-trigger","name":"TooltipTrigger","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/Tooltip/TooltipTrigger.cs","src_lines":[8,16],"src_base":"MonoBehaviour","src_implements":["IPointerEnterHandler","IPointerExitHandler"],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/Tooltip Trigger"},"src_typeComment":"Drop on any UI element (button, icon, panel) and set the text — hover shows the tooltip via TooltipSystem automatically.","src_serialized":[{"name":"tooltipText","type":"string","default":null,"tooltip":"Text shown in the tooltip when this element is hovered.","header":null,"range":null,"order":0,"comment":null}],"src_members":[{"id":"OnPointerEnter(PointerEventData)","sig":"public void OnPointerEnter(PointerEventData eventData) => TooltipSystem.Instance.Show(tooltipText)","kind":"method","name":"OnPointerEnter","static":false,"comment":null},{"id":"OnPointerExit(PointerEventData)","sig":"public void OnPointerExit(PointerEventData eventData) => TooltipSystem.Instance.Hide()","kind":"method","name":"OnPointerExit","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["MathAndUI_Demo"],"entryKind":"tool","status":"published","summary":"Set the text on any element and hovering shows the tooltip. No code.","overview":["Drop it on a button, icon or panel and set the text. Hover shows it through the tooltip system automatically."],"useCases":["Adding tooltips across a UI without a script per element.","Explaining icons that have no label."],"gotchas":[{"title":"It needs a tooltip system in the scene","body":"Without one, hovering does nothing. The trigger holds text; it does not draw anything itself."},{"title":"The text is fixed at author time","body":"For a tooltip whose content depends on state, call the system's Show directly instead."}],"seeAlso":["TooltipSystem"],"src_uses":["TooltipSystem"],"src_usedBy":["TooltipSystem"],"src_extensionPoints":[]}]}]},{"id":"loading-bar-ui","name":"LoadingBarUI","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/LoadingBar/LoadingBarUI.cs","src_lines":[36,128],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Loading Bar"},"src_typeComment":"Plug-and-play loading bar. HOW REAL LOADING PROGRESS ACTUALLY WORKS (read this before wiring anything — there is no single \"loading progress\" number Unity computes for you, only two real sources, and this component can be driven by either):  1) Unity's own AsyncOperation.progress — returned by SceneManager.LoadSceneAsync, AssetBundle. LoadFromFileAsync, Resources.UnloadUnusedAssets, Addressables, etc. The operation itself reports how far along it is; you just poll operation.progress every frame. Call Bind(operation) and this component does that polling for you automatically. GOTCHA specific to scene loads: SceneManager.LoadSceneAsync's progress caps at 0.9 and sits there until you explicitly set operation.allowSceneActivation = true — Unity deliberately holds back the last 10% so the new scene doesn't activate the instant loading finishes (giving you a chance to show \"Press any key\" or wait for a minimum display time first, the same thing Toolkit.UI. AsyncSceneLoader does). Use BindSceneLoad(operation) instead of Bind() for a scene-load operation — it remaps 0..0.9 -> 0..1 automatically so the bar still reaches a clean 100%.  2) A manually computed fraction — for anything that ISN'T a Unity AsyncOperation at all (a custom boot sequence, a multi-step save file, a fake splash-screen delay). YOU compute completedSteps / totalSteps (or bytesDownloaded / totalBytes, etc.) yourself and call SetProgress(that value) whenever it changes. SimulateProgress() below is a ready-made example of exactly this pattern with nothing real behind it — handy for building/testing a loading screen before the real work it represents exists yet.  Either way, the DISPLAYED bar doesn't snap straight to a new value — it smoothly chases it (smoothSpeed) instead. Real progress sources often jump in large, uneven steps (one asset bundle finishing, one big step out of ten completing), and a bar that visibly teleports looks broken even though the underlying number was completely accurate — smoothing is purely cosmetic, layered on top of the real progress.","src_serialized":[{"name":"slider","type":"Slider","default":null,"tooltip":"Auto-found on this GameObject or its children if left empty. Expects the default 0..1 min/max range.","header":null,"range":null,"order":0,"comment":null},{"name":"percentText","type":"TMP_Text","default":null,"tooltip":"Optional — shows the percentage as text, e.g. \"45%\". Leave empty if not needed.","header":null,"range":null,"order":1,"comment":null},{"name":"smoothSpeed","type":"float","default":"3f","tooltip":"How fast the visible bar chases the real target progress, in fraction-per-second. Higher = snappier/closer to the raw value, lower = smoother but laggier.","header":null,"range":null,"order":2,"comment":null}],"src_members":[{"id":"Bind(AsyncOperation)","sig":"public void Bind(AsyncOperation operation) => BindInternal(operation, remap: false)","kind":"method","name":"Bind","static":false,"comment":"Drives this bar from a real Unity AsyncOperation that does NOT have the scene-load 0.9 cap (an AssetBundle load, Resources.UnloadUnusedAssets, etc.) — polled automatically every frame from here on, no manual SetProgress calls needed."},{"id":"BindSceneLoad(AsyncOperation)","sig":"public void BindSceneLoad(AsyncOperation sceneLoadOperation) => BindInternal(sceneLoadOperation, remap: true)","kind":"method","name":"BindSceneLoad","static":false,"comment":"Same as Bind(), but for the specific case of SceneManager.LoadSceneAsync — remaps its 0..0.9 ceiling onto a clean 0..1 so the bar actually reaches 100% instead of visibly stalling at 90%. See the class header for why that cap exists."},{"id":"SetProgress(float)","sig":"public void SetProgress(float progress01)","kind":"method","name":"SetProgress","static":false,"comment":"For anything that ISN'T backed by a real AsyncOperation — call this yourself with completedSteps / totalSteps (or any other real 0..1 fraction) each time it changes."},{"id":"SimulateProgress(float, Action)","sig":"public void SimulateProgress(float duration, Action onComplete = null)","kind":"method","name":"SimulateProgress","static":false,"comment":"A fake, time-based progress fill with NO real work behind it — useful for prototyping a loading screen's look before the thing it represents exists yet. Swap this for Bind()/BindSceneLoad() or your own SetProgress() calls once there's something real to track — this is a placeholder, not a technique to ship with."}],"src_enumValues":[],"src_selfTest":"UI/LoadingBar/Editor/LoadingBarUISelfTest.cs","src_demoScene":["UIPolish_Demo"],"entryKind":"tool","status":"published","summary":"A loading bar that can be driven by real async progress or simulated, with smoothing.","overview":["Plug-and-play loading bar, and its documentation is blunt about the thing most loading bars get wrong: there is no single progress number Unity computes for you. There are only two real sources — an AsyncOperation's progress, and your own count of completed steps — and this can be driven by either, or told to simulate."],"useCases":["A scene-load bar driven by real progress.","A multi-step initialisation where you count the steps.","A deliberately simulated bar where there is nothing real to measure."],"params":[{"field":"smoothSpeed","tuning":"The visible bar chases the real target, so it never jumps. This is why a bar that leaps from 0 to 90 still looks like it filled."}],"gotchas":[{"title":"A simulated bar is a lie, and sometimes the right one","body":"It is offered explicitly rather than pretended to be real progress. Use it when there is genuinely nothing to measure, not to hide that you did not wire the real thing."}],"seeAlso":["AsyncSceneLoader","RadialProgressBar"],"src_uses":["AsyncSceneLoader"],"src_usedBy":[],"src_extensionPoints":[]},{"id":"radial-progress-bar","name":"RadialProgressBar","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/RadialProgressBar/RadialProgressBar.cs","src_lines":[10,53],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(Image)"],"addComponentMenu":"Toolkit/Radial Progress Bar"},"src_typeComment":"Drop on a UI Image — this auto-configures it for radial fill and exposes a simple SetProgress(0..1) API, so you don't have to remember the Image Type/Fill Method setup steps each time.","src_serialized":[{"name":"fillSpeed","type":"float","default":"4f","tooltip":"How quickly the bar eases toward the target value. 0 = snap instantly.","header":null,"range":null,"order":0,"comment":null},{"name":"fillOrigin","type":"Image.Origin360","default":"Image.Origin360.Top","tooltip":"Where the fill starts from.","header":null,"range":null,"order":1,"comment":null},{"name":"fillClockwise","type":"bool","default":"true","tooltip":"Fill direction around the circle.","header":null,"range":null,"order":2,"comment":null}],"src_members":[{"id":"SetProgress(float)","sig":"public void SetProgress(float normalizedValue) => targetFill = Mathf.Clamp01(normalizedValue)","kind":"method","name":"SetProgress","static":false,"comment":null},{"id":"SetProgressInstant(float)","sig":"public void SetProgressInstant(float normalizedValue)","kind":"method","name":"SetProgressInstant","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["MathAndUI_Demo","UIExtras_Demo"],"entryKind":"tool","status":"published","summary":"Auto-configures an Image for radial fill and exposes a simple SetProgress.","overview":["Drop it on a UI Image and it sets up the Image Type and Fill Method for radial fill, exposing a 0-1 API — so you do not have to remember the setup steps every time."],"useCases":["Ability cooldown rings.","A circular loading or charge indicator.","Hold-to-confirm progress."],"params":[{"field":"fillSpeed","tuning":"Zero snaps instantly, which is what a cooldown usually wants. Easing suits a charge-up."},{"field":"fillOrigin","tuning":"Top is conventional for cooldowns. Getting it wrong makes the ring fill from a strange place."}],"gotchas":[{"title":"It reconfigures the Image it is on","body":"The sprite must have a shape suitable for radial fill. A rectangular sprite fills as a rotating wedge, which looks wrong."}],"seeAlso":["CooldownAbilitySlot","LoadingBarUI","HoldToConfirmButton"],"src_uses":[],"src_usedBy":["CooldownAbilitySlot","HoldToConfirmButton"],"src_extensionPoints":[]},{"id":"fly-to-ui-effect","name":"FlyToUIEffect","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/FlyToUI/FlyToUIEffect.cs","src_lines":[23,146],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(RectTransform)"],"addComponentMenu":"Toolkit/UI/Fly To UI Effect"},"src_typeComment":"Plug-and-play \"reward fly\" feedback — the classic mobile-game \"coins arc from a pickup toward the wallet icon, then vanish\" effect. Answers the obvious performance question up front, two ways: 1) Pools icon instances via the EXISTING Toolkit.Core.ObjectPool instead of Instantiate/Destroy — repeated bursts over time reuse already-arrived instances instead of churning fresh GameObjects. 2) SpawnBurst caps how many icons are EVER visually spawned for one burst (maxVisualIcons) — a \"500 coins\" reward doesn't need 500 live objects on screen at once; cap the visual count and let a counter absorb the rest (add up the actual amount yourself in OnBurstComplete/OnIconArrived). Pooling alone can't reduce PEAK CONCURRENT instances for one genuinely simultaneous burst — only the visual cap can.","src_serialized":[{"name":"iconPrefab","type":"RectTransform","default":null,"tooltip":"The icon spawned per flying item (e.g. a coin Image), as a prefab or scene template. A CanvasGroup is added automatically if missing, for the fade-out.","header":null,"range":null,"order":0,"comment":null},{"name":"poolPrewarm","type":"int","default":"10","tooltip":null,"header":null,"range":null,"order":1,"comment":null},{"name":"flightDuration","type":"float","default":"0.6f","tooltip":null,"header":null,"range":null,"order":2,"comment":null},{"name":"burstStagger","type":"float","default":"0.04f","tooltip":"Delay between each icon's launch within a burst, in seconds.","header":null,"range":null,"order":3,"comment":null},{"name":"scatterRadius","type":"float","default":"40f","tooltip":"Random scatter radius applied to each icon's start position before it arcs to the target — 0 disables scatter.","header":null,"range":null,"order":4,"comment":null},{"name":"arcHeight","type":"float","default":"80f","tooltip":"How high the arc bulges above a straight line to the target, in UI units.","header":null,"range":null,"order":5,"comment":null},{"name":"ease","type":"EaseType","default":"EaseType.InQuad","tooltip":null,"header":null,"range":null,"order":6,"comment":null},{"name":"defaultMaxVisualIcons","type":"int","default":"12","tooltip":"Hard cap on how many icons a single SpawnBurst call will ever create, regardless of the requested count.","header":null,"range":null,"order":7,"comment":null}],"src_members":[{"id":"UnityEvent<int>()","sig":"public UnityEvent<int> OnIconArrived = new UnityEvent<int>()","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"UnityEvent()","sig":"public UnityEvent OnBurstComplete = new UnityEvent()","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"PendingInBurst","sig":"public int PendingInBurst => pendingInBurst","kind":"property","name":"PendingInBurst","static":false,"comment":"How many icons are still in flight from the most recent SpawnBurst — set synchronously the moment SpawnBurst is called (before any staggered coroutine actually runs), so it's a reliable way to confirm the visual cap took effect immediately, without needing to wait for icons to arrive."},{"id":"Spawn(Vector2, RectTransform, Action)","sig":"public void Spawn(Vector2 startScreenPosition, RectTransform target, Action onArrived = null)","kind":"method","name":"Spawn","static":false,"comment":"startScreenPosition/target are resolved via screen space, so either UI or world-space origins work — see SpawnBurstFromWorld for a world-position convenience overload."},{"id":"SpawnBurstFromWorld(Vector3, Camera, RectTransform, int, int)","sig":"public void SpawnBurstFromWorld(Vector3 worldPosition, Camera worldCamera, RectTransform target, int logicalCount, int maxVisualIcons = -1)","kind":"method","name":"SpawnBurstFromWorld","static":false,"comment":null},{"id":"SpawnBurst(Vector2, RectTransform, int, int)","sig":"public void SpawnBurst(Vector2 startScreenPosition, RectTransform target, int logicalCount, int maxVisualIcons = -1)","kind":"method","name":"SpawnBurst","static":false,"comment":"Spawns min(logicalCount, maxVisualIcons) icons from the same start position, staggered, all converging on target — pass the real reward amount as logicalCount even for huge rewards; only the capped visual count actually gets instantiated. maxVisualIcons &lt;= 0 uses defaultMaxVisualIcons."}],"src_enumValues":[],"src_selfTest":"UI/FlyToUI/Editor/FlyToUIEffectSelfTest.cs","src_demoScene":["UIDev_Demo"],"entryKind":"tool","status":"published","summary":"The coins-arc-to-the-wallet reward effect, pooled and capped so a big reward stays cheap.","overview":["The classic mobile reward feedback: icons arc from a pickup toward a UI target and vanish. It answers the obvious performance question up front in two ways — icons come from the existing object pool rather than Instantiate and Destroy, and a burst is capped so awarding a thousand coins does not spawn a thousand icons."],"useCases":["Coins or gems flying to the wallet on pickup.","XP orbs arcing to a level bar.","Any reward that should feel collected rather than just counted."],"params":[{"field":"defaultMaxVisualIcons","tuning":"The cap that keeps a large reward affordable. Players read a dozen icons as \"lots\" just as well as a hundred."},{"field":"burstStagger","tuning":"Zero launches them all at once, which reads as one blob rather than a stream."},{"field":"arcHeight","tuning":"Zero is a straight line and looks mechanical. The arc is most of the effect."}],"gotchas":[{"title":"Visual count is not the reward amount","body":"The cap means icons are decorative. Award the real value separately — never count the icons."}],"seeAlso":["ObjectPool","CurrencyWallet","FloatingCombatTextSpawner"],"src_uses":["BezierUtils","EaseType","EasingFunctions","ObjectPool","Tween"],"src_usedBy":["CombatTextMotion","CombatTextPreset","CombatTextStyle","FloatingCombatText","FloatingCombatTextSpawner","ObjectPool"],"src_extensionPoints":[]},{"id":"floating-combat-text-spawner","name":"FloatingCombatText","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/FloatingCombatText/FloatingCombatTextSpawner.cs","src_lines":[22,137],"src_base":"Singleton<FloatingCombatTextSpawner>","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Floating Combat Text Spawner"},"src_typeComment":"Plug-and-play \"floating combat text\" — damage/heal/miss/status numbers that pop up over a world-space hit point, drift, and fade (the classic RPG/action-game hit-feedback). A Singleton, same pattern as Toolkit.Tweening.FadeManager/ShaderTransitionManager: call FloatingCombatTextSpawner.Instance. SpawnDamage(...) from ANYWHERE (a Health/Combat script) with no manual Canvas wiring — it builds its own overlay canvas + pool the first time it's used.  `presets` IS the style dropdown: each entry is tagged with a CombatTextStyle and is fully editable right in the Inspector (color, size, motion, duration, drift) — add your own entries for new categories rather than editing code. Pooled via the existing Toolkit.Core.ObjectPool, same reuse trick as FlyToUIEffect.  Deliberately a ONE-SHOT screen-space conversion at spawn time, not continuous world tracking — correct for this tool's short (roughly 1 second) lifetime, and much simpler. If you need text that keeps following a moving target for longer than that, use Toolkit.UI.WorldSpaceUIFollow instead.","src_serialized":[{"name":"textPrefab","type":"GameObject","default":null,"tooltip":"Optional custom prefab (needs a TMP_Text + FloatingCombatText component). Leave empty to auto-build a plain default at runtime.","header":null,"range":null,"order":0,"comment":null},{"name":"worldCamera","type":"Camera","default":null,"tooltip":"Camera used to convert the world hit point to screen space. Defaults to Camera.main if left empty.","header":null,"range":null,"order":1,"comment":null},{"name":"poolPrewarm","type":"int","default":"8","tooltip":null,"header":null,"range":null,"order":2,"comment":null},{"name":"spawnJitterRadius","type":"float","default":"12f","tooltip":"Random screen-space scatter so several simultaneous hits don't perfectly overlap.","header":null,"range":null,"order":3,"comment":null},{"name":"presets","type":"CombatTextPreset[]","default":"BuildDefaultPresets()","tooltip":"The style presets Spawn()/SpawnDamage()/SpawnHeal()/SpawnMiss()/SpawnStatus() look up by CombatTextStyle. Edit freely, or add new CombatTextStyle values with their own entries.","header":null,"range":null,"order":4,"comment":null}],"src_members":[{"id":"Spawn(string, Vector3, CombatTextStyle)","sig":"public void Spawn(string text, Vector3 worldPosition, CombatTextStyle style)","kind":"method","name":"Spawn","static":false,"comment":"The general-purpose entry point — any style, any string."},{"id":"SpawnDamage(float, Vector3, bool)","sig":"public void SpawnDamage(float amount, Vector3 worldPosition, bool isCritical = false)","kind":"method","name":"SpawnDamage","static":false,"comment":null},{"id":"SpawnHeal(float, Vector3)","sig":"public void SpawnHeal(float amount, Vector3 worldPosition)","kind":"method","name":"SpawnHeal","static":false,"comment":null},{"id":"SpawnMiss(Vector3)","sig":"public void SpawnMiss(Vector3 worldPosition)","kind":"method","name":"SpawnMiss","static":false,"comment":null},{"id":"SpawnStatus(string, Vector3)","sig":"public void SpawnStatus(string label, Vector3 worldPosition)","kind":"method","name":"SpawnStatus","static":false,"comment":null},{"id":"FindPreset(CombatTextStyle)","sig":"public CombatTextPreset FindPreset(CombatTextStyle style)","kind":"method","name":"FindPreset","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["HitboxCombat_Demo"],"entryKind":"tool","status":"published","summary":"Damage and heal numbers popping over a world point, pooled, with style presets.","overview":["The classic RPG hit feedback: numbers pop over a world hit point, drift and fade. A singleton like the fade and transition managers, with presets so damage, heal, miss and status each have a consistent look you configure once."],"useCases":["Damage and healing numbers in combat.","Miss, block and critical callouts.","Status effect notifications over a character."],"params":[{"field":"spawnJitterRadius","tuning":"Random scatter so simultaneous hits do not stack into an unreadable pile. This is the setting that makes rapid combat legible."},{"field":"worldCamera","tuning":"Used to convert the world point to screen space. Defaults to the main camera, which breaks quietly with more than one."},{"field":"presets","tuning":"Where the look is defined per kind. Adding a new kind is a preset, not new code."}],"gotchas":[{"title":"It pools, so the prefab must be poolable","body":"A custom prefab needs the matching component so it can hand itself back. Without it, instances accumulate."}],"seeAlso":["FloatingCombatText","ObjectPool","WorldSpaceUIFollow"],"src_uses":["CombatTextMotion","CombatTextPreset","CombatTextStyle","FadeManager","FloatingCombatText","FlyToUIEffect","Health","ObjectPool"],"src_usedBy":["CombatTextMotion","CombatTextPreset","CombatTextStyle","FloatingCombatText","ObjectPool"],"src_extensionPoints":[],"isSystem":true,"systemOf":"FloatingCombatTextSpawner","systemPrimaryId":"floating-combat-text-spawner","systemSections":[{"title":"Supporting scripts","entries":[{"id":"floating-combat-text","name":"FloatingCombatText","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/FloatingCombatText/FloatingCombatText.cs","src_lines":[50,139],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(TMP_Text)"],"addComponentMenu":"Toolkit/UI/Floating Combat Text"},"src_typeComment":"One spawned instance's animation: pop-in scale, drift per its CombatTextMotion, fade-out over the last 30% of its lifetime, then hands itself back to FloatingCombatTextSpawner's pool. Kept as a separate component from the spawner (rather than one big class) so a custom prefab can be built/tested on its own, the same split FlyToUIEffect uses between the spawner and its pooled icon instances.","src_serialized":[],"src_members":[{"id":"Play(string, CombatTextPreset, Action<FloatingCombatText>)","sig":"public void Play(string text, CombatTextPreset config, Action<FloatingCombatText> onFinished)","kind":"method","name":"Play","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":"UI/FloatingCombatText/Editor/FloatingCombatTextSelfTest.cs","src_demoScene":[],"entryKind":"tool","status":"published","summary":"One spawned number's animation: pop, drift, fade, then return itself to the pool.","overview":["The per-instance half: pop-in scale, drift according to its motion preset, fade over the last part of its life, then hand itself back to the spawner's pool. Kept separate from the spawner so a custom prefab can be built and tested on its own."],"useCases":["A custom damage-number prefab with its own look.","Testing the animation without a combat scene.","Adding a motion style without touching the spawner."],"gotchas":[{"title":"It returns itself to the pool","body":"Do not destroy one yourself — that removes an instance the pool still believes it owns."}],"seeAlso":["FloatingCombatTextSpawner","PoolableObject"],"src_uses":["CombatTextMotion","CombatTextPreset","CombatTextStyle","FloatingCombatTextSpawner","FlyToUIEffect"],"src_usedBy":["CombatTextMotion","CombatTextPreset","CombatTextStyle","FloatingCombatTextSpawner"],"src_extensionPoints":[],"parts":[{"id":"combat-text-motion","name":"CombatTextMotion","cat":"UI","src_typeKind":"enum","src_ns":"Toolkit.UI","src_file":"UI/FloatingCombatText/FloatingCombatText.cs","src_lines":[18,24],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"How a spawned text drifts over its lifetime — kept separate from CombatTextStyle so a style can be \"Damage but with a shake\" just by editing one preset field, instead of needing a whole new style.","src_serialized":[],"src_members":[],"src_enumValues":["RiseStraight","RiseWithArc","RiseWithShake","HoverPulse"],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"How a spawned text drifts over its lifetime — kept separate from CombatTextStyle so a style can be \"Damage but with a...","src_uses":["CombatTextPreset","CombatTextStyle","FloatingCombatText","FloatingCombatTextSpawner","FlyToUIEffect"],"src_usedBy":["CombatTextPreset","CombatTextStyle","FloatingCombatText","FloatingCombatTextSpawner"],"src_extensionPoints":[],"foldedInto":"floating-combat-text"},{"id":"combat-text-style","name":"CombatTextStyle","cat":"UI","src_typeKind":"enum","src_ns":"Toolkit.UI","src_file":"UI/FloatingCombatText/FloatingCombatText.cs","src_lines":[7,14],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":["Damage","CriticalDamage","Heal","Miss","StatusEffect"],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"","src_uses":["CombatTextMotion","CombatTextPreset","FloatingCombatText","FloatingCombatTextSpawner","FlyToUIEffect"],"src_usedBy":["CombatTextMotion","CombatTextPreset","FloatingCombatText","FloatingCombatTextSpawner"],"src_extensionPoints":[],"foldedInto":"floating-combat-text"},{"id":"combat-text-preset","name":"CombatTextPreset","cat":"UI","src_typeKind":"struct","src_ns":"Toolkit.UI","src_file":"UI/FloatingCombatText/FloatingCombatText.cs","src_lines":[27,42],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[{"id":"style","sig":"public CombatTextStyle style","kind":"field","name":"style","static":false,"comment":null},{"id":"color","sig":"public Color color","kind":"field","name":"color","static":false,"comment":null},{"id":"fontSize","sig":"public float fontSize","kind":"field","name":"fontSize","static":false,"comment":null},{"id":"bold","sig":"public bool bold","kind":"field","name":"bold","static":false,"comment":null},{"id":"motion","sig":"public CombatTextMotion motion","kind":"field","name":"motion","static":false,"comment":null},{"id":"duration","sig":"public float duration","kind":"field","name":"duration","static":false,"comment":null},{"id":"riseDistance","sig":"public float riseDistance","kind":"field","name":"riseDistance","static":false,"comment":null},{"id":"horizontalAmount","sig":"public float horizontalAmount","kind":"field","name":"horizontalAmount","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"data","status":"skeleton","summary":"","src_uses":["CombatTextMotion","CombatTextStyle","FloatingCombatText","FloatingCombatTextSpawner","FlyToUIEffect"],"src_usedBy":["CombatTextMotion","CombatTextStyle","FloatingCombatText","FloatingCombatTextSpawner"],"src_extensionPoints":[],"foldedInto":"floating-combat-text"}]}]}]},{"id":"animated-number-counter","name":"AnimatedNumberCounter","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/NumberCounter/AnimatedNumberCounter.cs","src_lines":[25,89],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(TMP_Text)"],"addComponentMenu":"Toolkit/UI/Animated Number Counter"},"src_typeComment":"Drop on a TMP_Text and call SetValue(newValue) instead of writing text.text directly — the displayed number ticks smoothly toward the target instead of snapping, which reads much better for score/currency changes. numberFormat controls how the number itself is rendered; the separate `format` string still wraps it for a prefix/suffix (e.g. \"{0} coins\").","src_serialized":[{"name":"countDuration","type":"float","default":"0.5f","tooltip":"Seconds to animate from the current displayed value to a new target — recalculated each time SetValue() changes the target, so a big jump and a small jump both finish in the same time (a true constant-speed chase, not one that eases out as it nears the target).","header":null,"range":null,"order":0,"comment":null},{"name":"numberFormat","type":"NumberDisplayFormat","default":"NumberDisplayFormat.Integer","tooltip":"How the number itself is rendered.","header":null,"range":null,"order":1,"comment":null},{"name":"currencySymbol","type":"string","default":"\"$\"","tooltip":"Only used when Number Format is set to Currency.","header":null,"range":null,"order":2,"comment":null},{"name":"format","type":"string","default":"\"{0}\"","tooltip":"Optional prefix/suffix, e.g. \" coins\" — {0} is replaced with the formatted number.","header":null,"range":null,"order":3,"comment":null}],"src_members":[{"id":"SetValue(float, bool)","sig":"public void SetValue(float newValue, bool instant = false)","kind":"method","name":"SetValue","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":"UI/NumberCounter/Editor/AnimatedNumberCounterSelfTest.cs","src_demoScene":["Currency_Demo","UIPolish_Demo"],"entryKind":"tool","status":"published","summary":"Ticks a displayed number toward its target instead of snapping.","overview":["Call SetValue instead of writing to the text and the number counts up or down smoothly, which reads far better for score and currency changes. The number format controls how the value itself renders; a separate format string adds a prefix or suffix."],"useCases":["Score and currency that should feel earned.","A stat changing after an upgrade.","Any number where a jump would be missed by the player."],"params":[{"field":"countDuration","tuning":"Fixed regardless of how big the change is, so a huge jump counts at the same speed as a small one."},{"field":"format","tuning":"The prefix or suffix, with {0} standing in for the number — distinct from numberFormat, which decides how the number itself is written."}],"gotchas":[{"title":"Rapid SetValue calls retarget rather than queue","body":"Each call redirects the animation to the new target from wherever it currently is, which is what you want and means intermediate values are never shown."}],"seeAlso":["CurrencyWallet","NumberFormatter"],"src_uses":["NumberDisplayFormat","NumberFormatter"],"src_usedBy":["CurrencyWallet","NumberDisplayFormat"],"src_extensionPoints":[],"parts":[{"id":"number-display-format","name":"NumberDisplayFormat","cat":"UI","src_typeKind":"enum","src_ns":"Toolkit.UI","src_file":"UI/NumberCounter/AnimatedNumberCounter.cs","src_lines":[8,17],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":["Integer","Decimal1","Decimal2","Grouped","Compact","Currency","Percentage"],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"","src_uses":["AnimatedNumberCounter","NumberFormatter"],"src_usedBy":["AnimatedNumberCounter"],"src_extensionPoints":[],"foldedInto":"animated-number-counter"}]},{"id":"marquee-text","name":"MarqueeText","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/MarqueeText/MarqueeText.cs","src_lines":[19,91],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(RectMask2D)"],"addComponentMenu":"Toolkit/UI/Marquee Text"},"src_typeComment":"Plug-and-play horizontally auto-scrolling \"ticker\" text — for a string too long to fit its box, as an alternative to Toolkit.UI.TextAutoShrinkFitter for when shrinking the font isn't the right answer (a long item name, a news-ticker strip, a marquee credits line). Requires a RectMask2D on this GameObject to actually clip the overflow — without one, the text would just visibly slide past its box's edges.  Technique: a second copy of the label is instantiated, positioned exactly one \"loop length\" (text width + gap) to the right of the first. Both scroll left together at the same speed; whichever one scrolls fully past the left edge gets its position wrapped back around by one loop length. Two copies is always enough for a seamless infinite loop regardless of text length, since only one wrap can ever be \"due\" at a time.","src_serialized":[{"name":"label","type":"TMP_Text","default":null,"tooltip":"Auto-found among children if left empty.","header":null,"range":null,"order":0,"comment":null},{"name":"scrollSpeed","type":"float","default":"50f","tooltip":null,"header":null,"range":null,"order":1,"comment":null},{"name":"gapBetweenLoops","type":"float","default":"60f","tooltip":null,"header":null,"range":null,"order":2,"comment":null},{"name":"onlyScrollIfOverflowing","type":"bool","default":"true","tooltip":"If true, text that already fits the box just sits still instead of scrolling for no reason.","header":null,"range":null,"order":3,"comment":null}],"src_members":[{"id":"SetText(string)","sig":"public void SetText(string text)","kind":"method","name":"SetText","static":false,"comment":null},{"id":"ComputeWrappedScrollX(float, float, float)","sig":"public static float ComputeWrappedScrollX(float currentScrollX, float delta, float loopLength)","kind":"method","name":"ComputeWrappedScrollX","static":true,"comment":"The actual wrap-around math, pulled out as a pure function of its inputs (not label.preferredWidth directly) so it's testable without needing a real, laid-out TMP font — see MarqueeTextSelfTest. Public since the self-test lives in a separate Editor assembly."}],"src_enumValues":[],"src_selfTest":"UI/MarqueeText/Editor/MarqueeTextSelfTest.cs","src_demoScene":["UIExtras_Demo"],"entryKind":"tool","status":"published","summary":"Horizontally scrolling ticker text, for when shrinking the font is the wrong answer.","overview":["Scrolls text that is too long for its box, as the alternative to auto-shrinking — right for a long item name, a news ticker or a marquee credit line. It requires a RectMask2D on the object so the text is actually clipped."],"useCases":["A long item or track name in a narrow strip.","A news or status ticker.","Credits or announcements scrolling past."],"params":[{"field":"onlyScrollIfOverflowing","tuning":"Leave on. Text that already fits should sit still, not drift for no reason."},{"field":"gapBetweenLoops","tuning":"Zero makes the end run straight into the beginning, which is unreadable."}],"gotchas":[{"title":"It needs a RectMask2D","body":"Without one the text scrolls outside its box and over its neighbours."},{"title":"Scrolling text is hard to read","body":"It is the right answer for a name or a ticker, and the wrong one for anything the player must read carefully."}],"seeAlso":["TextAutoShrinkFitter"],"src_uses":["TextAutoShrinkFitter"],"src_usedBy":[],"src_extensionPoints":[]},{"id":"world-space-ui-follow","name":"WorldSpaceUIFollow","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/WorldSpaceUIFollow/WorldSpaceUIFollow.cs","src_lines":[9,54],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"requireComponent":["typeof(RectTransform)"],"addComponentMenu":"Toolkit/World Space UI Follow"},"src_typeComment":"Drop on a UI element (Image, Text, a whole health-bar panel) parented under a Canvas, assign a world Transform to follow — great for health bars, floating damage numbers, name tags.","src_serialized":[{"name":"worldTarget","type":"Transform","default":null,"tooltip":"World-space transform this UI element tracks.","header":null,"range":null,"order":0,"comment":null},{"name":"worldOffset","type":"Vector3","default":"new Vector3(0f, 2f, 0f)","tooltip":"Extra world-space offset added to the target's position before projecting to screen (e.g. above a character's head).","header":null,"range":null,"order":1,"comment":null},{"name":"worldCamera","type":"Camera","default":null,"tooltip":"Camera used to project world position to screen. Defaults to Camera.main if left empty.","header":null,"range":null,"order":2,"comment":null},{"name":"hideWhenBehindCamera","type":"bool","default":"true","tooltip":"Hides this element automatically when the target is behind the camera.","header":null,"range":null,"order":3,"comment":null}],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["MathAndUI_Demo"],"entryKind":"tool","status":"published","summary":"Keeps a UI element tracking a world transform, hiding it when behind the camera.","overview":["Drop it on a UI element under a Canvas and assign a world transform — for health bars, damage numbers and name tags that live in UI space but follow something in the world."],"useCases":["Enemy health bars above their heads.","Name tags and quest markers.","Interaction prompts anchored to an object."],"params":[{"field":"hideWhenBehindCamera","tuning":"Leave on. Without it, a target behind the camera projects to a mirrored on-screen position and the element appears in the wrong place."},{"field":"worldOffset","tuning":"How you get a bar above a head rather than at its feet, without an empty child transform."}],"gotchas":[{"title":"It does not scale with distance","body":"The element stays the same screen size however far away the target is. That is usually right for readability and wrong if you want depth."}],"seeAlso":["FloatingCombatTextSpawner","Health"],"src_uses":[],"src_usedBy":["FloatingCombatTextSpawner"],"src_extensionPoints":[]},{"id":"input-glyphs","name":"InputGlyphs","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/InputGlyph/InputGlyphSwapper.cs","src_lines":[12,41],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Input Glyph Swapper"},"src_typeComment":"Plug-and-play input prompt icon — drop on an Image showing something like \"Press [E] to interact\", and it automatically swaps to a gamepad button icon the moment the player picks up a controller (or back to keyboard/mouse the moment they touch the keyboard or mouse again), tracked by the shared InputDeviceMonitor. This is the \"don't hardcode one input method's icons\" problem every game that supports both keyboard/mouse AND gamepad eventually runs into.","src_serialized":[{"name":"keyboardMouseIcon","type":"Sprite","default":null,"tooltip":"Shown while the player is using keyboard & mouse.","header":null,"range":null,"order":0,"comment":null},{"name":"gamepadIcon","type":"Sprite","default":null,"tooltip":"Shown while the player is using a gamepad.","header":null,"range":null,"order":1,"comment":null},{"name":"targetImage","type":"Image","default":null,"tooltip":"Auto-found on this GameObject if left empty.","header":null,"range":null,"order":2,"comment":null}],"src_members":[{"id":"Refresh(InputDeviceKind)","sig":"public void Refresh(InputDeviceKind device)","kind":"method","name":"Refresh","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UIExtras_Demo"],"entryKind":"tool","status":"published","summary":"Swaps a prompt icon between keyboard and gamepad the moment the player switches device.","overview":["Drop it on an Image showing something like \"Press [E] to interact\" and it swaps to the gamepad icon the instant the player picks up a controller, and back when they touch the keyboard or mouse — tracked by the shared device monitor, so every prompt in the game switches together."],"useCases":["Interaction prompts that match the device in hand.","Tutorial hints that stay correct when a controller is connected mid-game.","Any UI showing a button icon."],"params":[{"field":"targetImage","tuning":"Auto-found on this GameObject if left empty, which covers the usual case."}],"gotchas":[{"title":"It swaps on the device KIND, not the specific pad","body":"Keyboard and mouse versus gamepad. Showing Xbox versus PlayStation glyphs is a further step this does not take."}],"seeAlso":["InputDeviceMonitor","LegacyInputManager"],"src_uses":["InputDeviceKind","InputDeviceMonitor"],"src_usedBy":["InputDeviceKind","InputDeviceMonitor"],"src_extensionPoints":[],"isSystem":true,"systemOf":"InputGlyphSwapper","systemPrimaryId":"input-glyph-swapper","systemSections":[{"title":"Supporting scripts","entries":[{"id":"input-device-monitor","name":"InputDeviceMonitor","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/InputGlyph/InputDeviceMonitor.cs","src_lines":[20,46],"src_base":null,"src_implements":[],"src_static":true,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"Tracks which KIND of input device the player most recently used — not a specific device, just \"keyboard & mouse\" vs \"gamepad\". This is what InputGlyphSwapper uses to decide which icon to show for a prompt like \"Press [E] to interact\" vs \"Press [Y] to interact\" — the swap happens automatically the instant the player's actual input changes, without you having to track it yourself anywhere.  A single shared static tracker rather than something each InputGlyphSwapper polls independently — a screen with a dozen prompt icons on it should still only be checking raw Input APIs once per frame, not once per icon.","src_serialized":[],"src_members":[{"id":"CurrentDevice","sig":"public static InputDeviceKind CurrentDevice { get; private set; } = InputDeviceKind.KeyboardMouse","kind":"property","name":"CurrentDevice","static":true,"comment":null},{"id":"OnDeviceChanged","sig":"public static event Action<InputDeviceKind> OnDeviceChanged","kind":"event","name":"OnDeviceChanged","static":true,"comment":null},{"id":"EnsureRunning()","sig":"public static void EnsureRunning()","kind":"method","name":"EnsureRunning","static":true,"comment":"Called automatically by InputGlyphSwapper — you don't need to call this yourself unless you want the monitor running before any glyph icon exists (e.g. to read InputDeviceMonitor.CurrentDevice early)."},{"id":"ReportActivity(InputDeviceKind)","sig":"public static void ReportActivity(InputDeviceKind device)","kind":"method","name":"ReportActivity","static":true,"comment":"Public rather than internal so both InputDeviceMonitorRunner AND a self-test (which lives in a separate Editor assembly) can call it directly — also handy if you ever want to force the current device from your own code (e.g. defaulting to Gamepad on console platforms)."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"published","summary":"Tracks which KIND of device was used most recently, and fires when it changes.","overview":["Reports keyboard-and-mouse versus gamepad — not a specific device. This is what the glyph swapper reads to decide which icon to show, and the swap happens the instant the player touches the other device.","The actual per-frame polling lives in a separate runner component rather than in this static tracker, so the tracker needs no scene object of its own."],"useCases":["Driving every prompt icon in the game from one source.","Hiding a mouse cursor when a gamepad is picked up.","Switching UI navigation behaviour by input kind."],"gotchas":[{"title":"It reports the last used, not the connected","body":"A connected but untouched gamepad does not change the answer, which is what you want — the icons follow the player's hands, not the hardware."}],"seeAlso":["InputGlyphSwapper"],"src_uses":["InputDeviceKind","InputDeviceMonitorRunner","InputGlyphSwapper"],"src_usedBy":["InputDeviceKind","InputDeviceMonitorRunner","InputGlyphSwapper"],"src_extensionPoints":[],"parts":[{"id":"input-device-kind","name":"InputDeviceKind","cat":"UI","src_typeKind":"enum","src_ns":"Toolkit.UI","src_file":"UI/InputGlyph/InputDeviceMonitor.cs","src_lines":[6,10],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":["KeyboardMouse","Gamepad"],"src_selfTest":null,"src_demoScene":[],"entryKind":"enum","status":"skeleton","summary":"","src_uses":["InputDeviceMonitor","InputDeviceMonitorRunner","InputGlyphSwapper"],"src_usedBy":["InputDeviceMonitor","InputDeviceMonitorRunner","InputGlyphSwapper"],"src_extensionPoints":[],"foldedInto":"input-device-monitor"},{"id":"input-device-monitor-runner","name":"InputDeviceMonitorRunner","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/InputGlyph/InputDeviceMonitorRunner.cs","src_lines":[22,55],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"The actual per-frame polling behind InputDeviceMonitor — split into its own MonoBehaviour (rather than living on the static InputDeviceMonitor class itself) since a static class can't have Update()/OnEnable().  Two detection paths, both always compiled in, so this works whether or not the project has the Input System package installed: - Legacy (always active): Input.anyKeyDown / mouse-delta for keyboard&mouse, and KeyCode.JoystickButton0 through 19 for gamepad — that specific range works with ZERO Input Manager axis configuration (no project-specific setup needed), unlike stick/trigger movement, which legacy Input can't reliably read without pre-authored axes. So legacy gamepad detection only catches button presses, not stick movement — an honest, deliberate scope limit, not an oversight. - New Input System (only compiled when the package is present): subscribes to InputSystem.onEvent directly, which reports the exact device that produced each real input event — Keyboard/Mouse vs Gamepad — far more precise than polling, and does catch stick/trigger movement too.","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"skeleton","summary":"The actual per-frame polling behind InputDeviceMonitor — split into its own MonoBehaviour (rather than living on the...","src_uses":["InputDeviceKind","InputDeviceMonitor"],"src_usedBy":["InputDeviceKind","InputDeviceMonitor"],"src_extensionPoints":[],"foldedInto":"input-device-monitor"}]}]}]},{"id":"undo-redo","name":"UndoRedo","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/UndoRedo/CommandHistory.cs","src_lines":[11,65],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{"addComponentMenu":"Toolkit/UI/Command History"},"src_typeComment":"Undo/Redo stack — Execute() runs an ICommand immediately and records it; Undo()/Redo() walk back and forth. A new Execute() after undoing clears the redo stack, the standard \"a new action invalidates the old future\" rule every undo/redo system follows.","src_serialized":[{"name":"maxHistorySize","type":"int","default":"100","tooltip":"Maximum commands kept in undo history. The oldest is discarded once exceeded.","header":null,"range":null,"order":0,"comment":null}],"src_members":[{"id":"UnityEvent()","sig":"public UnityEvent OnHistoryChanged = new UnityEvent()","kind":"method","name":"UnityEvent","static":false,"comment":null},{"id":"CanUndo","sig":"public bool CanUndo => undoStack.Count > 0","kind":"property","name":"CanUndo","static":false,"comment":null},{"id":"CanRedo","sig":"public bool CanRedo => redoStack.Count > 0","kind":"property","name":"CanRedo","static":false,"comment":null},{"id":"Execute(ICommand)","sig":"public void Execute(ICommand command)","kind":"method","name":"Execute","static":false,"comment":null},{"id":"Undo()","sig":"public bool Undo()","kind":"method","name":"Undo","static":false,"comment":null},{"id":"Redo()","sig":"public bool Redo()","kind":"method","name":"Redo","static":false,"comment":null},{"id":"Clear()","sig":"public void Clear()","kind":"method","name":"Clear","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":["UIDev_Demo"],"entryKind":"tool","status":"published","summary":"Undo and redo stack. A new action after undoing clears the redo future.","overview":["Execute runs a command immediately and records it; Undo and Redo walk back and forth. A fresh Execute after undoing clears the redo stack — the standard rule every undo system follows, because the old future no longer applies."],"useCases":["A level or map editor's undo.","A form with revert-changes.","Any tool where a mistake should be reversible."],"params":[{"field":"maxHistorySize","tuning":"The oldest is discarded past this. Commands holding large data (a whole texture) make this a memory decision, not just a convenience one."}],"gotchas":[{"title":"Only what you route through it can be undone","body":"Changing state directly is invisible to the stack and leaves undo doing something inconsistent."}],"seeAlso":["ICommand","ActionCommand"],"src_uses":["ICommand"],"src_usedBy":["ActionCommand","ICommand"],"src_extensionPoints":["ICommand"],"isSystem":true,"systemOf":"CommandHistory","systemPrimaryId":"command-history","systemSections":[{"title":"Supporting scripts","entries":[{"id":"i-command","name":"ICommand","cat":"UI","src_typeKind":"interface","src_ns":"Toolkit.UI","src_file":"UI/UndoRedo/ICommand.cs","src_lines":[8,12],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"Standard Command pattern — wrap a reversible action, push it onto a CommandHistory, and Undo()/Redo() walk back and forth. Not tied to UI specifically despite living alongside the other UI-dev tools — works for anything from a level editor's placement tool to a form's \"revert changes\" button.","src_serialized":[],"src_members":[{"id":"Execute()","sig":"void Execute()","kind":"method","name":"Execute","static":false,"comment":null},{"id":"Undo()","sig":"void Undo()","kind":"method","name":"Undo","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"contract","status":"published","summary":"Execute and Undo. Wrap a reversible action and let the history walk it back and forth.","purpose":"The standard Command pattern. Not UI-specific despite living beside the UI tools — it works for a level editor's placement tool or a form's revert button equally.","whenToImplement":"When an action needs to be reversible. If it cannot be undone cleanly, it does not belong in the history at all.","memberContracts":{"Execute()":{"contract":"Do the action. Called once when first executed, and again on every redo, so it must produce the same result each time.","mustNot":"Do not capture the state you need to undo INSIDE Execute. Capture it at construction — by redo time the world has already changed."},"Undo()":{"contract":"Put things back exactly as they were. Called with the world in the state Execute left it.","mustNot":"Do not assume Execute ran immediately before. Several commands may have been undone in between, so undo must depend only on state captured at construction."}},"calledBy":"CommandHistory: Execute when first run and on every redo, Undo when walking back. Nothing else should call either — calling Execute directly bypasses the history and makes undo inconsistent.","drivenBy":["CommandHistory"],"useCases":["Placing and removing objects in an editor.","A property change that should be revertible.","Batched operations undone as one step."],"gotchas":[{"title":"Redo re-runs Execute, it does not replay a recording","body":"So Execute must be repeatable and must not depend on the state it happens to find."}],"seeAlso":["CommandHistory","ActionCommand"],"src_uses":["ActionCommand","CommandHistory"],"src_usedBy":["ActionCommand","CommandHistory"],"src_extensionPoints":[],"parts":[{"id":"action-command","name":"ActionCommand","cat":"UI","src_typeKind":"class","src_ns":"Toolkit.UI","src_file":"UI/UndoRedo/ICommand.cs","src_lines":[16,29],"src_base":null,"src_implements":["ICommand"],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"Wraps two plain delegates as an ICommand — covers the common case without writing a new class per action type.","src_serialized":[],"src_members":[{"id":"ActionCommand(Action, Action)","sig":"public ActionCommand(Action execute, Action undo)","kind":"ctor","name":"ActionCommand","static":false,"comment":null},{"id":"Execute()","sig":"public void Execute() => executeAction?.Invoke()","kind":"method","name":"Execute","static":false,"comment":null},{"id":"Undo()","sig":"public void Undo() => undoAction?.Invoke()","kind":"method","name":"Undo","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"skeleton","summary":"Wraps two plain delegates as an ICommand — covers the common case without writing a new class per action type.","src_uses":["CommandHistory","ICommand"],"src_usedBy":["ICommand"],"src_extensionPoints":["ICommand"],"foldedInto":"i-command"}]}]}]}],"groups":[{"title":"Layout & Fitting","ids":["accordion-panel","card-carousel","masonry-layout-group","radial-layout-group","aspect-ratio-image-fitter","text-auto-shrink-fitter","deferred-layout-rebuilder","layout-rebuild-helper","safe-area-handler"]},{"title":"Scrolling","ids":["fancy-scroll-view","scroll-snap","pull-to-refresh","timed-line-scroll-view"]},{"title":"Navigation","ids":["screen-stack-navigator","tab-group","pagination-dots","async-scene-loader"]},{"title":"Input & Controls","ids":["drag-and-drop","draggable-ui-panel","hold-to-confirm-button","toggle-switch"]},{"title":"Feedback & Overlays","ids":["toast-notification","modal-dialog","tooltips","loading-bar-ui","radial-progress-bar"]},{"title":"Motion & Effects","ids":["fly-to-ui-effect","floating-combat-text-spawner","animated-number-counter","marquee-text","world-space-ui-follow"]},{"title":"Device & Platform","ids":["input-glyphs"]},{"title":"Undo / Redo","ids":["undo-redo"]}]};
